export default {'food-industry--fiqc-aquatic':[['food-industry--fiqc-aquatic--ความสำคัญของการควบคุมคุณภาพสัตว์น้ำ','ความสำคัญของการควบคุมคุณภาพสัตว์น้ำ','ความสำคัญของการควบคุมคุณภาพสัตว์น้ำ \n ปลาที่คนทั่วโลกบริโภคในปัจจุบันมาจาก aquaculture ประมาณ 50% ไม่ได้มาจากการจับจากธรรมชาติเป็นหลักอีกต่อไป \n ประชากรโลก 1 ใน 3 คน พึ่งสัตว์น้ำเป็นแหล่งโปรตีนจากสัตว์ที่สำคัญ (ตัวเลขตามสไลด์) แต่ fao sofia 2024 ระบุว่าปี 2021 มีประชากร 3.2 พันล้านคน ที่ได้โปรตีนจากสัตว์น้ำ อย่างน้อย 20% ของโปรตีนจากสัตว์ทั้งหมด ซึ่งเทียบกับประชากรโลกราว 8 พันล้านคนแล้วใกล้ 2 ใน 5 มากกว่า 1 ใน 3 และในภาพรวมอาหารจากสัตว์น้ำให้โปรตีนจากสัตว์ราว 15% ของโลก \n ไทยติด top 10 ผู้ส่งออก processed seafood ของโลก \n ความปลอดภัยของอาหารจากสัตว์น้ำถูกวางกรอบเป็นประเด็น one health คือเชื่อมสุขภาพสัตว์ สุขภาพคน และสุขภาพสิ่งแวดล้อมเข้าด้วยกัน \n ในปี 2022 ผลผลิต aquaculture คิดเป็น 51% (94.4 ล้านตัน) ของผลผลิตสัตว์น้ำทั้งหมด 185 ล้านตัน ซึ่งเป็นครั้งแรกที่ aquaculture แซง capture fisheries ในการผลิตสัตว์น้ำ \n อาหารจากสัตว์น้ำให้โปรตีนจากสัตว์ประมาณ 15% ของโลก และในปี 2021 ให้โปรตีนจากสัตว์อย่างน้อย 20% ต่อหัวแก่ประชากร 3.2 พันล้านคน \n สิ่งแวดล้อมบริเวณปากแม่น้ำที่เชื่อมกับการเพาะเลี้ยงสัตว์น้ำของไทยเป็นแหล่งสะสมเชื้อดื้อยา โดยพบ salmonella 96.9% และ e. coli 91.4% ดื้อยาอย่างน้อยหนึ่งชนิด ผู้วิจัยจึงเสนอให้ใช้กรอบ one health เพื่อป้องกันการแพร่ของเชื้อดื้อยา'],['food-industry--fiqc-aquatic--ภาพรวมการเพาะเลี้ยงและประมงระดับโลก','ภาพรวมการเพาะเลี้ยงและประมงระดับโลก','ภาพรวมการเพาะเลี้ยงและประมงระดับโลก \n มูลค่าการส่งออกปลาและอาหารทะเลของโลกอยู่ที่ประมาณ us$150 พันล้านต่อปีขึ้นไป \n ผลผลิตประมงและเพาะเลี้ยงของโลกประมาณ 35% เข้าสู่การค้าระหว่างประเทศ (ตัวเลขตามสไลด์) แต่ fao sofia 2024 รายงานปี 2022 ว่ามีการส่งออก 70 ล้านตัน (live weight equivalent) คิดเป็น 38% ของผลผลิตสัตว์น้ำทั้งหมด และมูลค่าการค้าระหว่างประเทศสูงเป็นประวัติการณ์ที่ usd 195 พันล้าน ซึ่งไม่ขัดกับที่สไลด์เขียนว่า us$150 พันล้านขึ้นไป แต่สูงกว่ามาก \n กราฟแนวโน้ม capture เทียบ aquaculture แสดงว่า capture fisheries ค่อนข้างคงที่ตั้งแต่ปี 2000 ถึง 2023 ขณะที่ aquaculture เพิ่มขึ้นชันและ แซง capture ในช่วงปี 2020 ถึง 2023 (แกน y สเกล 0 ถึง 120 แต่สไลด์ไม่ได้พิมพ์หน่วยกำกับไว้) \n กลุ่มสัตว์น้ำเพาะเลี้ยงหลัก 4 กลุ่มของโลก \n finfish ได้แก่ carps, tilapia, salmon, catfish, seabass เป็นสัดส่วนผลผลิตมากที่สุดของ aquaculture โลก \n crustaceans โดย whiteleg shrimp และ giant tiger prawn ครองสินค้าส่งออกมูลค่าสูง \n molluscs ได้แก่ oysters, mussels, clams, scallops โดยเฉพาะแถบชายฝั่งเอเชีย \n aquatic plants คือสาหร่ายและ algae เป็นกลุ่มที่มีสัดส่วนโดยปริมาณสูงและโตเร็ว \n ในปี 2022 การค้าสินค้าสัตว์น้ำระหว่างประเทศมีมูลค่าสูงเป็นประวัติการณ์ที่ usd 195 พันล้าน โดยมีการส่งออก 70 ล้านตัน (live weight equivalent) คิดเป็น 38% ของผลผลิตสัตว์น้ำทั้งหมด \n ในช่วง 1997 ถึง 2017 การเพาะเลี้ยงสัตว์น้ำในแหล่งน้ำจืด (inland aquaculture) โดยเฉพาะในเอเชีย เป็นกลุ่มที่มีส่วนต่อปริมาณผลผลิตของโลกและต่อความมั่นคงทางอาหารมากที่สุด \n การเลี้ยง molluscs และ seaweed ได้รับการยอมรับมากขึ้นในแง่ ecosystem services และศักยภาพของสองกลุ่มนี้ต่อความมั่นคงทางโภชนาการของโลกยังถูกใช้ประโยชน์ไม่เต็มที่'],['food-industry--fiqc-aquatic--อุตสาหกรรมสัตว์น้ำไทย-พัฒนาการและอันดับโลก','อุตสาหกรรมสัตว์น้ำไทย พัฒนาการและอันดับโลก','อุตสาหกรรมสัตว์น้ำไทย พัฒนาการและอันดับโลก \n 5 ยุคของการเพาะเลี้ยงสัตว์น้ำไทย \n 1970s ถึง 1980s ขยายการเลี้ยงในบ่อน้ำจืดและการเลี้ยงกุ้งชายฝั่ง \n 1990s บูมกุ้งกุลาดำแบบ intensive ทำให้ไทยขึ้นเป็นผู้ส่งออกอันดับต้นของโลก \n 2000s เปลี่ยนมาสู่กุ้งขาว พร้อมการเติบโตของ tilapia และ pangasius \n 2010s การระบาดของโรค เช่น ems ผลักดันการลงทุนด้าน biosecurity และ traceability \n ปัจจุบัน เน้นผลผลิตที่ได้รับการรับรอง ตรวจสอบย้อนกลับได้ และควบคุมสารตกค้างเพื่อการส่งออก \n อันดับและมูลค่าของไทย \n ไทยอยู่ top 10 ของโลกด้าน marine aquaculture และ top 11 ด้าน inland aquaculture \n ในการผลิตทางทะเลและชายฝั่ง ไทยอยู่อันดับ #6 ของ crustaceans และ #10 ของ molluscs \n มูลค่าส่งออกสินค้าประมงและสัตว์น้ำของไทย us$6 พันล้านขึ้นไปต่อปี และมี มากกว่า 100 ประเทศ นำเข้าสินค้าสัตว์น้ำสดและแปรรูปจากไทย \n อันดับโลก crustacean aquaculture (หน่วยพันตัน) \n ไทยอยู่อันดับ #6 ที่ 436 พันตัน \n สามอันดับแรกคือ china 7,848, viet nam 1,370 และ india 1,315 พันตัน ส่วนกลุ่มประเทศที่เหลือไม่รวม top 3 รวมกัน 3,794 พันตัน \n อันดับอื่นบนกราฟเดียวกัน #4 ecuador 1,218, #5 indonesia 984, #7 mexico 216, #8 bangladesh 168, #9 brazil 147, #10 philippines 81 พันตัน \n ตั้งแต่ปี 2003 กุ้งขาว penaeus (litopenaeus) vannamei ที่มาจากสายพันธุ์คัดเลือกและเลี้ยงในระบบปิด เข้ามาแทนที่กุ้งกุลาดำ penaeus monodon ในฐานะชนิดกุ้งที่เพาะเลี้ยงเป็นหลักในเอเชีย \n ems/ahpnd ทำให้อุตสาหกรรมกุ้งในเอเชียสูญเสียผลผลิตอย่างมหาศาล โดยอาจทำให้กุ้งในบ่อตายสะสมถึง 100% ภายในหนึ่งสัปดาห์ และการศึกษาแบบ case-control ในฟาร์มกุ้ง 4 จังหวัดของไทยระบุปัจจัยด้านการจัดการฟาร์มและการเตรียมน้ำที่สัมพันธ์กับการเกิดโรค'],['food-industry--fiqc-aquatic--ตัวเลขผลผลิตสัตว์น้ำของไทยรายชนิดและวิธีเลี้ยง','ตัวเลขผลผลิตสัตว์น้ำของไทยรายชนิดและวิธีเลี้ยง','ตัวเลขผลผลิตสัตว์น้ำของไทยรายชนิดและวิธีเลี้ยง \n กุ้ง \n กุ้งรวมทุกชนิดแบบ intensive 23,731 ฟาร์ม, 385,677 ตัน, 57,952.5 ล้านบาท ส่วนแบบ semi-intensive 2,969 ฟาร์ม, 2,992 ตัน, 660 ล้านบาท \n pacific white shrimp เป็นกุ้งหลักของไทย intensive 372,655 ตัน มูลค่า 55,147.4 ล้านบาท เทียบกับ semi-intensive เพียง 978 ตัน มูลค่า 147.8 ล้านบาท (จำนวนฟาร์มไม่มีข้อมูล na) \n tiger prawn intensive 13,022 ตัน มูลค่า 2,805 ล้านบาท semi-intensive 1,798 ตัน มูลค่า 478.6 ล้านบาท (จำนวนฟาร์ม na) \n กุ้งก้ามกราม (giant freshwater prawn) เลี้ยงในบ่อ 11,227 ฟาร์ม, 40,675 ตัน, 7,482.4 ล้านบาท \n ตัวเลขในสไลด์เปรียบเทียบให้เห็นเองว่า tiger prawn ต่ำกว่า pacific white shrimp ประมาณหนึ่งลำดับขั้ม (order of magnitude) ใช้จำภาพรวมว่ากุ้งขาวคือกุ้งส่งออกหลักของไทย \n ปลา \n tilapia บ่อ 332,390 ฟาร์ม / 209,124 ตัน / 9,079 ล้านบาท, นาข้าว 399 / 226 / 10.3, ร่องสวน 4,501 / 2,661 / 130.3, กระชัง 5,868 / 50,079 ตัน / 3,123 ล้านบาท \n catfish บ่อ 85,139 ฟาร์ม / 99,876 ตัน / 4,394 ล้านบาท, นาข้าว 114 / 41 / 2.5, ร่องสวน 1,447 / 893 / 53, กระชัง 191 / 769 / 25 \n seabass บ่อ 2,252 ฟาร์ม / 39,714 ตัน / 3,790 ล้านบาท, กระชัง 4,285 ฟาร์ม / 5,701 ตัน / 771 ล้านบาท \n กุ้งขาวเป็นชนิดกุ้งที่เพาะเลี้ยงเป็นหลักแทนกุ้งกุลาดำ ซึ่งสอดคล้องกับภาพรวมในสไลด์ที่ผลผลิต pacific white shrimp ของไทยสูงกว่า tiger prawn ประมาณหนึ่งลำดับขั้น'],['food-industry--fiqc-aquatic--ชนิดสัตว์น้ำเศรษฐกิจหลักและระบบการเลี้ยงสมัยใหม่','ชนิดสัตว์น้ำเศรษฐกิจหลักและระบบการเลี้ยงสมัยใหม่','ชนิดสัตว์น้ำเศรษฐกิจหลักและระบบการเลี้ยงสมัยใหม่ \n รอบการเลี้ยงและความเสี่ยงหลักรายชนิด \n whiteleg shrimp (litopenaeus vannamei) สัตว์น้ำกลุ่ม crustacean ส่งออกอันดับหนึ่งของไทย รอบเลี้ยงประมาณ 90 ถึง 120 วัน จาก postlarvae ถึงขนาดจับ ในบ่อดินหรือบ่อปูผ้าใบแบบ intensive ที่มีการให้อากาศ ความเสี่ยงหลักคือโรคไวรัส เช่น wssv, early mortality syndrome และความล้มเหลวของคุณภาพน้ำ \n nile tilapia (oreochromis niloticus) ได้ขนาดตลาดในราว 5 ถึง 6 เดือน เลี้ยงในบ่อดินและกระชังในแม่น้ำหรืออ่างเก็บน้ำ เชื้อแบคทีเรียที่ระบุชื่อไว้คือ streptococcus ร่วมกับปัญหาคุณภาพน้ำและการสัมผัสสารชีวฆาต (biocide)หรือโลหะ \n pangasius หรือ striped catfish (pangasianodon hypophthalmus) ได้ขนาดตลาดในราว 6 ถึง 8 เดือน เลี้ยงหนาแน่นในบ่อและกระชังในแม่น้ำที่มีการให้อากาศเชิงกล ความเสี่ยงคือการติดเชื้อปรสิตและแบคทีเรีย รวมถึงภาระน้ำทิ้งและสารอินทรีย์ \n seabass, grouper และปลาทะเลอื่น ได้ขนาดตลาดในราว 8 ถึง 12 เดือน แล้วแต่ชนิด เลี้ยงในกระชังลอยทะเลและบ่อดินชายฝั่ง ความเสี่ยงคือ sea lice และปรสิต, harmful algal blooms และ biofouling ของกระชัง \n ระบบเลี้ยงทางเลือก \n ras (recirculating aquaculture system) กรองและหมุนเวียนน้ำในระบบปิด ให้ biosecurity สูง เลี้ยงหนาแน่นได้ ใช้น้ำน้อย แต่ต้นทุนลงทุนและพลังงานสูง \n biofloc จัดการ microbial flocs เพื่อหมุนเวียนสารอาหาร ใช้การเปลี่ยนถ่ายน้ำน้อยมาก เพิ่มประสิทธิภาพอาหารและลดน้ำทิ้ง แต่ต้องควบคุมการให้อากาศและติดตามระบบอย่างใกล้ชิด \n ประมาณ 60% ของความสูญเสียจากโรคในการเลี้ยงกุ้งเกิดจากเชื้อไวรัส และ 20% จากเชื้อแบคทีเรีย โดย white spot syndrome virus (wssv) และ yellow head virus (yhv) เป็นไวรัสที่ทำให้ตายรุนแรงที่สุดทั้งในกุ้งขาวและกุ้งกุลาดำ \n streptococcus spp. เป็นแบคทีเรียก่อโรคหลักที่ทำให้ปลานิลตายเป็นจำนวนมาก โดยในภาคเหนือของไทยแยกเชื้อได้จากฟาร์มกระชังในแม่น้ำ 4 จาก 33 ฟาร์ม ขณะที่ฟาร์มบ่อดิน 28 ฟาร์มตรวจไม่พบ และ streptococcus agalactiae เป็นชนิดเด่น \n biofloc technology (bft) เลี้ยงที่ความหนาแน่นสูงโดยเปลี่ยนถ่ายน้ำน้อยที่สุด ช่วยเพิ่มประสิทธิภาพการเปลี่ยนอาหารและ biosecurity กำจัด inorganic nitrogen ออกจากน้ำทิ้ง และหมุนเวียนสารอาหารกลับมาใช้ใหม่อย่างต่อเนื่อง'],['food-industry--fiqc-aquatic--ห่วงโซ่คุณค่า-การจับ-การแปรรูป-บรรจุ-และ-cold-chain','ห่วงโซ่คุณค่า การจับ การแปรรูป บรรจุ และ cold chain','ห่วงโซ่คุณค่า การจับ การแปรรูป บรรจุ และ cold chain \n ห่วงโซ่คุณค่าสัตว์น้ำ 5 ขั้น \n broodstock และ hatchery ผลิตลูกพันธุ์และควบคุมคุณภาพทางพันธุกรรม \n grow-out farming เลี้ยงในบ่อ กระชัง หรือ ras จนได้ขนาดตลาด \n harvest การจับและการจัดการเบื้องต้นที่ฟาร์ม \n processing ล้าง ตัดแต่ง แช่เย็นหรือแช่แข็ง \n distribution และ market โลจิสติกส์แบบ cold chain สู่ผู้ซื้อในประเทศหรือส่งออก \n การจับและสวัสดิภาพที่รักษาคุณภาพเนื้อ 4 ข้อ \n pre-harvest fasting ลดปริมาณอาหารในทางเดินอาหารและของเสียจากเมแทบอลิซึมก่อนฆ่า \n humane slaughter โดยการทำสลบหรือลดอุณหภูมิอย่างรวดเร็ว ลดความเครียดและทำให้คุณภาพเนื้อดีขึ้น \n minimizing injury ใช้อวนและจัดการอย่างระมัดระวัง ลดรอยช้ำและความเสียหายของผิวหนัง \n rapid chilling ลงน้ำแข็งทันที ชะลอการเติบโตของจุลินทรีย์และการเน่าเสีย \n อุณหภูมิและรูปแบบผลิตภัณฑ์ \n การจัดการหลังจับแบบแช่เย็น ต้องลงน้ำแข็งทันทีให้อุณหภูมิแกนกลางอยู่ราว 0 ถึง 4 องศาเซลเซียส ใช้น้ำแข็งและภาชนะระดับ food-grade และคุมความสัมพันธ์ของเวลากับอุณหภูมิเพื่อจำกัดการเติบโตของแบคทีเรีย \n live มูลค่าสูงสุดแต่อายุการเก็บสั้นที่สุด \n fresh หรือ chilled ที่ 0 ถึง 4 องศาเซลเซียส ขายภายในไม่กี่วัน \n frozen ที่ ลบ 18 องศาเซลเซียสหรือต่ำกว่า เก็บได้เป็นเดือน โดยการแช่แข็งแบบ blast หรือ iqf ช่วยรักษาเนื้อสัมผัสและคุณภาพ \n ขั้นตอนในโรงงานแปรรูป 5 ขั้น \n receiving ตรวจคุณภาพวัตถุดิบขาเข้า \n washing และ sorting ทำความสะอาดและคัดขนาดคัดคุณภาพ \n cutting หรือ filleting เตรียมเป็นรูปแบบผลิตภัณฑ์ที่ต้องการ \n chilling หรือ freezing ลดอุณหภูมิอย่างรวดเร็วเพื่อความปลอดภัย \n packing บรรจุแบบปิดผนึกและติดฉลากเพื่อการขนส่ง \n ผลิตภัณฑ์แปรรูปเพิ่มมูลค่า 4 กลุ่ม \n surimi-based โปรตีนปลาบดที่ผ่านการล้างและทำให้บริสุทธิ์ ใช้ทำปูอัดและลูกชิ้นปลา \n canned ผ่านความร้อนจนเก็บได้ที่อุณหภูมิห้อง เช่น ทูน่ากระป๋อง \n ready-to-eat ปรุงสุก ชุบแป้ง หรือหมัก ต้องคุม cold chain และสุขลักษณะอย่างเข้มงวด \n fermented น้ำปลาและผลิตภัณฑ์ปลาหมัก \n cold chain และฉลาก \n จุดควบคุม cold chain 4 จุดคือ packaging วัสดุ food-grade ที่ป้องกันการปนเปื้อน, labeling ชื่อชนิดสัตว์น้ำ แหล่งกำเนิด รหัส batch หรือ lot และวันที่ผลิตเพื่อการตรวจสอบย้อนกลับ, cold storage ควบคุมอุณหภูมิที่ผ่านการ validate ทุกจุดจัดเก็บ และ transport monitoring ใช้ time-temperature logger ยืนยันความต่อเนื่องของ cold chain ระหว่างขนส่ง \n กฎน้ำหนักสุทธิบนฉลาก คือ น้ำหนักสุทธิเฉลี่ยต้องไม่น้อยกว่าน้ำหนักสุทธิที่แจ้งบนฉลาก, จำนวนหน่วยบรรจุที่มีน้ำหนักต่ำกว่ามาตรฐานที่แจ้งต้องไม่เกิน tolerable deficiency หรือ acceptance number ที่กำหนดใน sampling plan และความสมบูรณ์ของภาชนะบรรจุต้องเป็นไปตามข้อกำหนดของ cfia (canadian food inspection agency) \n สไลด์เน้นว่าเหตุการณ์ temperature abuse เพียงครั้งเดียวสามารถทำลายความปลอดภัยของสินค้าได้ แม้การควบคุมต้นน้ำทั้งหมดจะดีอยู่แล้ว \n การปล่อยให้สินค้าอยู่ที่อุณหภูมิสูงเพียงช่วงสั้นระหว่างการแปรรูป (temperature abuse) ก็ทำให้อายุการเก็บของปลาแช่เย็นสั้นลงอย่างวัดได้ โดยการถือฟิลเลต saithe ไว้ที่ 16 องศาเซลเซียส นาน 1 และ 2 ชั่วโมงก่อนบรรจุ ทำให้สูญเสียอายุการเก็บ 22% (2 วัน) และ 44% (4 วัน) ตามลำดับ เทียบกับฟิลเลตที่บรรจุทันทีหลังแปรรูป \n การจัดการก่อนฆ่าและวิธีทำสลบมีผลต่อคุณภาพเนื้อโดยตรง ปลานิลที่ผ่านความหนาแน่นสูง (300 กก. น้ำหนักมีชีวิตต่อลูกบาศก์เมตร) ร่วมกับการทำให้ตายด้วยการขาดอากาศ (asphyxia) มีความเครียดมากกว่า เนื้อฟิลเลตแน่นน้อยกว่า สูญเสียน้ำหนักจากการปรุงมากกว่า และมีความเสียหายของกล้ามเนื้อมากกว่า ขณะที่ความหนาแน่นต่ำ (50 กก./ลบ.ม.) ร่วมกับการทำสลบด้วยการลดอุณหภูมิ (thermonarcosis) ทำให้อยู่ในระยะ pre rigor mortis นานกว่าและได้ profile ทางประสาทสัมผัสที่ดีกว่า \n ปลาสดเป็นอาหารที่เน่าเสียง่ายมากและมีอายุการเก็บสั้น จึงต้องผ่านการจัดการและเก็บรักษาอย่างถูกต้องเพื่อชะลอการเสื่อมสภาพและประกันความปลอดภัยทางจุลชีววิทยา โดยวิธีเก็บรักษาแบบดั้งเดิมคือการแช่เย็น (refrigeration) และการแช่เยือกแข็ง (freezing)'],['food-industry--fiqc-aquatic--อันตรายทางชีวภาพในสัตว์น้ำ','อันตรายทางชีวภาพในสัตว์น้ำ','อันตรายทางชีวภาพในสัตว์น้ำ \n อันตรายในอาหารแบ่งเป็น 3 กลุ่มคือ biological (แบคทีเรียก่อโรค ไวรัส ปรสิต ที่ทำให้คนป่วยหรือกระทบอายุการเก็บ), chemical (สารตกค้างยาสัตว์ โลหะหนัก สารชีวฆาต (biocide)และสารชีวพิษธรรมชาติ) และ physical (เศษกระดูก เบ็ด แก้ว โลหะ หรือพลาสติกที่ปนเข้ามาระหว่างการจัดการหรือแปรรูป) \n vibrio spp. \n เป็นแบคทีเรีย halophilic ในทะเล พบตามธรรมชาติในน้ำชายฝั่งและปากแม่น้ำที่อุ่น (สไลด์เหมารวมทั้งสกุล) แต่ฉลาก halophilic ใช้ได้แม่นเฉพาะ v. parahaemolyticus และ v. vulnificus ส่วน v. cholerae ถือเป็น non-halophilic และ vibrio พบได้ทั้งในน้ำจืดและน้ำทะเล สะสมในหอยกรองอาหาร ทำให้เกิด gastroenteritis, wound infection หรือ septicaemia รุนแรงในกลุ่มเปราะบาง \n ลักษณะเชื้อคือ gram-negative, facultative anaerobic, comma-shaped \n สามชนิดสำคัญคือ v. parahaemolyticus, v. vulnificus และ v. cholerae \n v. cholerae ทำให้เกิดอหิวาตกโรค อาการท้องร่วงรุนแรง บางรายขาดน้ำและอาจถึงตาย อุบัติการณ์ 11 ล้านรายต่อปี infective dose 1 ล้านตัวเชื้อ อาหารที่เกี่ยวข้องคือน้ำและหอยที่ปนเปื้อน \n v. parahaemolyticus และ v. vulnificus ไม่ทำให้เกิดอหิวาตกโรค แต่ทำให้ป่วยจากอาหารทะเลปนเปื้อน อุบัติการณ์ 4,500 ราย สำหรับ v. parahaemolyticus และ 96 ราย สำหรับ v. vulnificus, infective dose 1 ล้านตัวเชื้อ อาหารที่เกี่ยวข้องคืออาหารทะเลดิบหรือปรุงไม่สุก โดยเฉพาะหอยนางรม \n แบคทีเรียก่อโรคอื่น \n listeria monocytogenes เติบโตได้ที่อุณหภูมิตู้เย็น จึงเป็นประเด็นสำคัญเป็นพิเศษในผลิตภัณฑ์ ready-to-eat \n salmonella spp. เชื่อมโยงกับน้ำหรืออาหารสัตว์ที่ปนเปื้อน หรือการปนเปื้อนข้ามระหว่างการแปรรูป \n e. coli เป็นตัวชี้วัดการปนเปื้อนอุจจาระและเป็น marker ของสุขลักษณะโดยรวม \n จุดที่สไลด์เน้นคือ listeria monocytogenes โตได้ทั้งที่อุณหภูมิแช่เย็น การพึ่ง cold chain อย่างเดียวจึงไม่พอสำหรับสินค้า rte \n ปรสิตและไวรัส \n opisthorchis viverrini เป็นพยาธิใบไม้ตับที่ติดจากปลา น้ำจืด ดิบหรือสุกไม่ทั่วถึง \n anisakis spp. เป็นพยาธิตัวกลมของปลา ทะเล ที่เป็นปัญหาในปลาดิบหรือแปรรูปเบา \n วงจรชีวิตของทั้งคู่มักผ่าน intermediate host เช่น หอยและปลา การควบคุมคือปรุงสุกทั่วถึง แช่แข็งตามเวลาและอุณหภูมิที่ validate แล้ว และการให้ความรู้ผู้บริโภค \n wssv (white spot syndrome virus) ในกุ้งเป็นไวรัสด้านสุขภาพสัตว์ที่สำคัญทางเศรษฐกิจแต่ ไม่ใช่ zoonotic \n ตรงข้ามกับไวรัสในคนอย่าง norovirus และ hepatitis a ที่ปนเปื้อนหอยจากน้ำเสีย โดยเส้นทางการปนเปื้อนคือน้ำในแหล่งจับ \n จำคู่ตรงข้ามที่สไลด์วางไว้ให้ ปลาน้ำจืดเท่ากับ opisthorchis viverrini ปลาทะเลเท่ากับ anisakis spp. \n vibrio เป็นแบคทีเรียที่พบทั่วไปในแหล่งน้ำและทะเล โดย v. cholerae ทำให้เกิดอหิวาตกโรคซึ่งเป็นโรคท้องร่วงรุนแรงที่อาจถึงตายอย่างรวดเร็วถ้าไม่รักษา และมักติดต่อผ่านน้ำที่ปนเปื้อน ส่วน vibrio กลุ่ม non-cholera เช่น v. parahaemolyticus และ v. vulnificus ทำให้เกิด vibriosis จากการสัมผัสน้ำทะเลหรือกินอาหารทะเลดิบหรือปรุงไม่สุก โดย v. vulnificus เป็น opportunistic pathogen ที่มีอัตราตายสูงและทำให้เกิด wound infection ที่ลุกลามเป็น septicaemia ได้เร็ว \n ผลิตภัณฑ์ ready-to-eat อย่าง cold smoked salmon มีอายุการเก็บสั้นแม้อยู่ในสภาพแช่เย็น และยังรองรับการเจริญของ listeria monocytogenes ได้ การพึ่ง cold chain อย่างเดียวจึงไม่เพียงพอ ต้องใช้เวลาและอุณหภูมิร่วมกันเป็นเกณฑ์ควบคุมความเสี่ยง listeriosis \n opisthorchis viverrini เป็นพยาธิใบไม้ตับที่คนติดจากการกินปลาน้ำจืดวงศ์ cyprinid ดิบหรือปรุงไม่สุกทั่วถึง ประมาณ 10 ล้านคนในเอเชียตะวันออกเฉียงใต้ติดเชื้อชนิดนี้ และพยาธิใบไม้ตับกลุ่มนี้ได้รับการพิสูจน์แล้วว่าเป็นสาเหตุของมะเร็งท่อน้ำดี (cholangiocarcinoma)'],['food-industry--fiqc-aquatic--อันตรายทางเคมี-กายภาพ-สารก่อภูมิแพ้-และ-amr','อันตรายทางเคมี กายภาพ สารก่อภูมิแพ้ และ AMR','อันตรายทางเคมี กายภาพ สารก่อภูมิแพ้ และ amr \n สารตกค้างยาสัตว์ \n withdrawal period มีไว้เพื่อให้ความเข้มข้นของยาลดลงต่ำกว่า mrl (maximum residue limit) \n สาเหตุรากของการตกค้างเกินคือ withdrawal time ไม่พอ, การใช้ยานอกฉลาก (off-label use) หรืออาหารและน้ำที่ปนเปื้อน \n malachite green ถูกระบุชื่อไว้ว่าเป็นสารที่ไม่อนุญาตให้ใช้ \n ผลที่ตามมาคือสินค้าถูกปฏิเสธ (shipment rejection) ถูกแบนจากตลาด และเกิดการคัดเลือกเชื้อดื้อยา \n โลหะหนัก \n โลหะหนักสำคัญ 4 ตัวคือ mercury (hg), lead (pb), cadmium (cd) และ arsenic (as) \n สะสมในเนื้อเยื่อ (bioaccumulate) และสูงกว่าในสัตว์นักล่าหรือสัตว์อายุยืน \n แหล่งที่มาคือน้ำทิ้งอุตสาหกรรม อาหารหรือน้ำที่ปนเปื้อน และการสะสมในตะกอนดิน \n histamine และสารชีวพิษทางทะเล \n histamine เกิดในปลาที่มี histidine สูง เช่น ทูน่าและแมคเคอเรล เมื่อเกิด temperature abuse \n marine biotoxins ที่สไลด์ระบุคือ ciguatera และ paralytic shellfish poisoning (psp) ซึ่งเกิดจาก harmful algal blooms \n การควบคุมคือลดอุณหภูมิอย่างรวดเร็วหลังการจับ ร่วมกับการเฝ้าระวังสารพิษในพื้นที่แหล่งจับ \n จุดที่สไลด์ขีดเส้นใต้ไว้ชัดคือ histamine และสารชีวพิษหลายชนิด ไม่ถูกทำลายด้วยความร้อนจากการปรุงอาหาร เช่นเดียวกับโลหะหนักที่ไม่สลายไปด้วยการปรุงหรือแปรรูป การควบคุมจึงต้องเกิดตั้งแต่ต้นทาง \n เดคนี้ให้เนื้อหาสารพิษทางทะเลเพียงหน้าเดียว ระบุแค่ชื่อกลุ่มอาการ ciguatera และ psp ว่ามาจาก harmful algal blooms ไม่ได้ระบุชนิดสาหร่ายหรือ dinoflagellate ต้นเหตุ ไม่มีอาการทางคลินิก ไม่มีค่ากำหนดเชิงตัวเลขใดๆ และไม่มี dsp, asp, nsp, azp หรือ tetrodotoxin เลย เช่นเดียวกับดัชนีความสดอย่าง tvb-n หรือ k-value ที่ไม่ปรากฏในเดคนี้ \n อันตรายทางกายภาพ สารก่อภูมิแพ้ และ amr \n สิ่งปนเปื้อนทางกายภาพคือเศษกระดูก เบ็ด โลหะ แก้ว หรือพลาสติกจากอุปกรณ์ ตรวจจับด้วย metal detector และ x-ray inspection ที่ขั้นตอนวิกฤตของกระบวนการผลิต \n โปรตีนของปลาและ crustacean เป็น สารก่อภูมิแพ้อาหารหลักที่ได้รับการยอมรับ ควบคุมด้วยการบำรุงรักษาเครื่องจักร การแยกสายการผลิต และการติดฉลากสารก่อภูมิแพ้ที่ถูกต้อง โดยเน้นการป้องกันด้วยการออกแบบกระบวนการ ไม่ใช่พึ่งการตรวจผลิตภัณฑ์สุดท้ายเพียงอย่างเดียว \n องค์กรระหว่างประเทศ 4 แห่งที่ให้ความสำคัญกับการเฝ้าระวัง amr ในการเพาะเลี้ยงสัตว์น้ำคือ who, woah, fao และ unep \n การใช้ยาปฏิชีวนะและ biocide อย่างไม่เหมาะสมสามารถ co-select เชื้อดื้อยาในสภาพแวดล้อมฟาร์ม และยีนดื้อยากับ mobile element สามารถแพร่ข้าม interface ของสัตว์น้ำ สัตว์ และคนได้ \n histamine ในปลาเกิดจากการที่แบคทีเรีย decarboxylate free l-histidine หลังการจัดการที่ไม่เหมาะสม จึงเกิดได้เฉพาะปลาที่มี free l-histidine สูงซึ่งพบในปลาผิวน้ำ (pelagic) บางชนิดเท่านั้น และเนื่องจากต้องอาศัย time-and-temperature abuse การควบคุมจึงเป็นการจัดการที่ถูกต้องโดยระบุอันตรายและจุดวิกฤต (haccp) ร่วมกับการรักษา cold chain ตั้งแต่จับจนถึงผู้บริโภค \n malachite green เป็นสารที่ห้ามใช้ในสัตว์ที่ใช้เป็นอาหาร แต่ยังตรวจพบสารตกค้างของ malachite green และ metabolite หลักคือ leucomalachite green ในปลา จากการลักลอบใช้ในการเพาะเลี้ยงสัตว์น้ำและจากน้ำทิ้งอุตสาหกรรม ซึ่งเป็นความเสี่ยงต่อความปลอดภัยอาหารและสิ่งแวดล้อม \n มีรายงานจำนวนมากว่า v. vulnificus และ v. parahaemolyticus แสดงการดื้อยาหลายขนาน (multiple-antibiotic resistance) อันเป็นผลจากการใช้ยาปฏิชีวนะอย่างไม่เหมาะสมเพื่อควบคุมโรคในการเพาะเลี้ยงสัตว์น้ำ และการมีเชื้อดื้อยาหลายขนานในอาหารทะเลและสิ่งแวดล้อมทางน้ำเป็นประเด็นสำคัญทั้งต่อการเลี้ยงปลากับหอยและต่อสุขภาพคน'],['food-industry--fiqc-aquatic--ระบบควบคุมคุณภาพ-gap-และมาตรฐานสินค้าเกษตรของไทย','ระบบควบคุมคุณภาพ GAP และมาตรฐานสินค้าเกษตรของไทย','ระบบควบคุมคุณภาพ gap และมาตรฐานสินค้าเกษตรของไทย \n พีระมิดควบคุมคุณภาพ 5 ชั้นจากฟาร์มถึงตลาด \n gap good aquaculture practices ระดับฟาร์ม \n gmp good manufacturing practice สร้างสภาพแวดล้อมการแปรรูปที่ถูกสุขลักษณะ \n haccp ควบคุมอันตรายอย่างเป็นระบบที่จุดวิกฤต \n iso และ codex ระบบการจัดการและมาตรฐานอ้างอิงระหว่างประเทศ \n certification การตรวจรับรองโดยบุคคลที่สามเพื่อเปิดทางเข้าสู่ตลาด \n gap ในประเทศไทย \n การรับรอง gap ออกโดย กรมประมง (department of fisheries) และเป็นเงื่อนไขเบื้องต้นของตลาดส่งออกหลายแห่ง \n ขอบเขตครอบคลุมการเลือกสถานที่ คุณภาพน้ำ การจัดการอาหารและยา และ biosecurity \n การบันทึกข้อมูลครอบคลุมปัจจัยการผลิต การรักษา และเหตุการณ์การตาย \n การทวนสอบทำโดย การตรวจฟาร์มเป็นระยะ โดยหน่วยงานรัฐหรือหน่วยรับรองบุคคลที่สามที่ได้รับการรับรองระบบงาน \n องค์ประกอบของ gap สัตว์น้ำ กรมประมง มี 7 องค์ประกอบ ได้แก่ สถานที่, ปัจจัยการผลิต, การจัดการ, สุขลักษณะฟาร์ม, การจัดการดูแลสุขภาพสัตว์น้ำ, การเก็บเกี่ยวและการขนส่ง และการเก็บข้อมูล \n มาตรฐานสินค้าเกษตรของไทย \n ณ วันที่ 11 มิถุนายน 2565 ไทยมี 388 มาตรฐานสินค้าเกษตรที่ประกาศใช้ แบ่งเป็น 8 มาตรฐานบังคับ และ 381 มาตรฐานทั่วไป และแบ่งอีกทางเป็น 199 มาตรฐานระบบ, 132 มาตรฐานสินค้า และ 57 มาตรฐานข้อกำหนดทั่วไป \n มาตรฐานบังคับทั้ง 8 ฉบับคือ มกษ 4702-2557 (ปริมาณอะฟลาทอกซินในเมล็ดถั่วลิสง), มกษ 1004-2557 (การรมผลไม้สดด้วยซัลเฟอร์ไดออกไซด์), มกษ 6401-2558 (ศูนย์รวบรวมน้ำนมดิบ), มกษ 7432-2558 (gap สำหรับโรงเพาะฟักลูกกุ้งขาวแวนนาไมปลอดโรค ซึ่งเป็นฉบับเดียวที่เกี่ยวกับสัตว์น้ำ), มกษ 6413-2563 (ปางช้าง), มกษ. 6909-2562 (ฟาร์มไก่ไข่), มกษ. 9046-2560 (การผลิตทุเรียนแช่เยือกแข็ง) และ มกษ. 2507-2559 (การผลิตหัวเชื้อเห็ด) \n เลขในสไลด์หน้าเดียวกันไม่ลงตัวกันเอง หัวเรื่องเขียน 388 มาตรฐาน แต่กิ่งซ้ายรวมได้ 8 บวก 381 เท่ากับ 389 ขณะที่กิ่งขวารวมได้ 199 บวก 132 บวก 57 เท่ากับ 388 บันทึกไว้ตามที่พิมพ์จริงในสไลด์ \n โครงสร้าง มกษ. 7432-2558 \n มาตรฐานสินค้าเกษตร gap สำหรับโรงเพาะฟักลูกกุ้งขาวแวนนาไม (litopenaeus vannamei) ปลอดโรค แบ่งเป็น 7 หัวข้อเรียงลำดับ คือ 1. หลักการผลิต, 2. บุคลากร, 3. การคัดเลือกพ่อแม่พันธุ์กุ้งขาวแวนนาไมปลอดโรค, 4. การจัดการทั่วไป, 5. การจัดการด้านอาหารของพ่อแม่พันธุ์, 6. การจัดการสุขภาพ และ 7. บันทึกข้อมูล \n การจัดการระดับฟาร์มที่ gap ครอบคลุม โดยเฉพาะการจัดการน้ำและ biosecurity ลดการเกิดโรคได้จริงในบริบทไทย การศึกษาระยะยาวในฟาร์มกุ้งทะเลที่ระยองพบว่าการแยกบ่อออกเป็น 3 ประเภทคือบ่อเลี้ยง บ่อบำบัดน้ำ และบ่อพักน้ำ เป็นปัจจัยป้องกันการเกิดโรคตัวแดงดวงขาว (white spot disease) อย่างมีนัยสำคัญ (or = 0.0828)'],['food-industry--fiqc-aquatic--gmp-haccp-iso-traceability-และ-codex','GMP, HACCP, ISO, Traceability และ Codex','gmp, haccp, iso, traceability และ codex \n gmp \n ขอบเขตของ gmp คือการออกแบบอาคารสถานที่ การสุขาภิบาล สุขลักษณะส่วนบุคคล การควบคุมสัตว์พาหะ และความปลอดภัยของน้ำ \n จัดทำเอกสารผ่าน ssops (standard sanitation operating procedures) และบันทึกการทำความสะอาด และเป็นข้อกำหนดสำหรับการขออนุญาตโรงงานแปรรูปอาหารในเขตอำนาจส่วนใหญ่ \n สไลด์วงล้อ gmp ในเดคแสดงเพียงหัวข้อ 6 ด้าน คือ location, personnel, machinery, maintenance, processing และ sanitary โดยไม่มีเนื้อหาอธิบายใต้หัวข้อ \n ประเด็นที่สไลด์เน้นคือ ต้องมี gmp ก่อน haccp จึงจะทำงานได้จริง gmp เป็น prerequisite ที่สร้างสภาพแวดล้อมถูกสุขลักษณะให้ haccp ไปต่อยอด \n haccp \n สไลด์จัดกลุ่ม หลักการ 7 ข้อ ไว้ดังนี้ หลักการ 1 ถึง 2 วิเคราะห์อันตรายและระบุ ccp, หลักการ 3 ถึง 4 กำหนด critical limit และเฝ้าระวัง, หลักการ 5 ถึง 6 แก้ไขเมื่อเบี่ยงเบนและทวนสอบว่าระบบใช้ได้ผล, หลักการ 7 การจัดทำเอกสารและบันทึกที่พิสูจน์ว่าระบบถูกปฏิบัติจริง \n haccp เป็นระบบเชิงป้องกันที่อิงหลักวิทยาศาสตร์ ไม่ใช่การตรวจผลิตภัณฑ์สุดท้ายเพียงอย่างเดียว \n haccp ในโรงงานอาหารทะเล จับคู่ขั้นตอนกับอันตราย \n receiving raw material เชื้อก่อโรค การเน่าเสีย (decomposition) และสารตกค้างยาสัตว์ \n chilling หรือ icing การเกิด histamine และการเจริญของเชื้อก่อโรค \n metal detection สิ่งปนเปื้อนทางกายภาพ \n cooking สำหรับสินค้า rte การรอดชีวิตของเชื้อก่อโรค \n packaging และ labeling การติดฉลากสารก่อภูมิแพ้ผิด \n cold storage และ transport temperature abuse และการเกิดสารพิษ \n iso และ codex \n iso 22000 food safety management systems วางโครงบน 4 องค์ประกอบคือ interactive communication, system management, prps (prerequisite programmes) และหลักการ haccp และใช้ได้ตลอด ทั้งห่วงโซ่อาหาร รวมถึงผู้ผลิตอาหารสัตว์ \n iso 9001 เป็นมาตรฐานการจัดการคุณภาพทั่วไปที่ ไม่เฉพาะเจาะจงด้านความปลอดภัยอาหาร องค์ประกอบหลักคือขั้นตอนที่เป็นเอกสาร การตรวจติดตามภายใน การแก้ไข และการทบทวนของฝ่ายบริหาร มักใช้ควบคู่กับ iso 22000 หรือ haccp \n traceability ทำงานบนหลัก one step back, one step forward ทุกผู้เล่นในห่วงโซ่ต้องรู้ผู้ส่งมอบและลูกค้าที่อยู่ติดกับตน ข้อมูลที่เก็บคือแหล่งฟาร์ม เลข batch หรือ lot วันที่จับ และประวัติการแปรรูป ใช้ barcode, qr code และ blockchain มากขึ้น และเป็นข้อกำหนดสำหรับ catch documentation scheme และการรับรองเพื่อการส่งออก \n codex alimentarius จัดทำร่วมกันโดย fao และ who มี code of practice for fish and fishery products สถานะทางกฎหมายเป็น voluntary แต่ถูกใช้เป็นมาตรฐานอ้างอิงในข้อพิพาททางการค้าของ wto เนื้อหาครอบคลุม mrls, hygiene codes, การติดฉลาก และแนวทางกระบวนการที่อิง haccp \n คู่ที่สไลด์วางให้เทียบกันตรงๆ คือ iso 22000 เป็นเรื่องความปลอดภัยอาหารทั้งห่วงโซ่ ส่วน iso 9001 เป็นคุณภาพทั่วไปที่ไม่ใช่ food-safety specific \n สุขลักษณะการผลิตพื้นฐานคือจุดที่ระบบล้มเหลวมากที่สุดจริง จากการทบทวนการเรียกคืนสินค้าประมงในสหรัฐกว่า 2,400 ครั้ง ระหว่างตุลาคม 2002 ถึงมีนาคม 2022 พบว่า 74% ของการเรียกคืนเกิดจากการละเมิดข้อกำหนด current good manufacturing practices (cgmps) และผู้เขียนสรุปว่าการนำหลัก haccp ไปใช้อย่างถูกต้องเป็นสิ่งจำเป็นในการระบุความเสี่ยงด้านความปลอดภัยอาหาร \n codex alimentarius commission ดำเนินการร่วมกันโดย fao และ who และความตกลง sps กับ tbt ขององค์การการค้าโลกอาศัยมาตรฐาน แนวปฏิบัติ และข้อแนะนำของ codex ที่อิงวิทยาศาสตร์ เป็น benchmark ในการตัดสินข้อพิพาททางการค้าอาหารระหว่างประเทศ \n ระบบตรวจสอบย้อนกลับของห่วงโซ่สินค้าประมงมีเป้าหมายติดตามและสอบกลับผลิตภัณฑ์ตลอดตั้งแต่การจับ การแปรรูป การบรรจุ การขนส่ง จนถึงการกระจายสินค้าปลายทาง และยืนยันความถูกต้องแท้จริงของสินค้าตลอดห่วงโซ่ โดยมีการนำ blockchain และ iot มาสร้างระบบที่โปร่งใสและช่วยป้องกันกับตรวจจับการทำประมงผิดกฎหมาย ขาดการรายงาน และไร้การควบคุม (iuu)'],['food-industry--fiqc-aquatic--การเข้าถึงตลาดส่งออกและกรอบกำกับดูแล','การเข้าถึงตลาดส่งออกและกรอบกำกับดูแล','การเข้าถึงตลาดส่งออกและกรอบกำกับดูแล \n ข้อกำหนดรายตลาด \n eu สถานประกอบการที่ส่งออกต้องอยู่ในบัญชี eu-listed และถูกตรวจสม่ำเสมอ ต้องมีทั้ง health certificate และ catch certificate แนบไปกับทุก shipment มี mrl เข้มงวดสำหรับยาสัตว์และสารปนเปื้อน และมี iuu regulation ที่ใช้ catch certification เพื่อต่อต้านการประมงผิดกฎหมาย ขาดการรายงาน และไร้การควบคุม \n us ฐานกฎหมายคือ us seafood haccp regulation 21 cfr part 123 โดย fda บังคับใช้ haccp กับอาหารทะเลทั้งในประเทศและนำเข้าตั้งแต่กลางทศวรรษ 1990 ผู้นำเข้าสหรัฐต้องทวนสอบว่าผู้ส่งมอบต่างประเทศทำตามข้อกำหนด haccp และ fsma foreign supplier verification program เพิ่มความรับผิดชอบของผู้นำเข้า การบังคับใช้ทำผ่านการตรวจของ fda, import alert และ automatic detention สำหรับผู้ละเมิดซ้ำ \n japan ใช้ระบบ positive list ที่กำหนด mrl เข้มงวด พร้อมการสุ่มตรวจและตรวจแบบเจาะจง และมีความคาดหวังสูงด้านประสาทสัมผัสและคุณภาพของสินค้าสดและมีชีวิต ส่วน china มีมาตรฐานภายในประเทศที่เติบโตขึ้นควบคู่กับความต้องการนำเข้าอาหารทะเลที่สูงขึ้น จุดร่วมของทั้งคู่คือทั้งสองประเทศต้องการสถานประกอบการส่งออกที่ขึ้นทะเบียนและเอกสารที่ชัดเจน \n หน่วยงานและมาตรฐานของไทย \n tas หรือ มกษ. (thai agricultural standards) กำหนดโดยสำนักงานมาตรฐานสินค้าเกษตรและอาหารแห่งชาติ \n dof code of conduct คือโปรแกรมการเพาะเลี้ยงอย่างรับผิดชอบระดับฟาร์มของกรมประมง \n thai fda ดูแลความปลอดภัยและการติดฉลากของอาหารแปรรูปภายในประเทศ \n มาตรฐานระดับชาติออกแบบให้สอดคล้องกับ codex และกฎของตลาดส่งออก \n fiqd = fish inspection and quality control division (กองตรวจสอบคุณภาพสินค้าประมง) กรมประมง ให้บริการตรวจโรงงานและดูแลมาตรฐานผลิตภัณฑ์สัตว์น้ำ 3 หมวด คือ ทางกายภาพ, ทางเคมี และทางจุลชีววิทยา โดยสไลด์แสดงเพียงชื่อหมวด ไม่ได้แสดงค่ากำหนดเชิงตัวเลขของแต่ละหมวด \n กระบวนการตรวจสอบและรับรองเพื่อการส่งออก 5 ขั้น \n farm certification ตรวจและขึ้นทะเบียนตาม gap หรือ coc \n plant approval ตรวจ gmp และ haccp และขึ้นบัญชีโรงงาน \n lot testing ตรวจสารตกค้าง เชื้อก่อโรค และคุณภาพรายล็อต \n health certificate ออกใบรับรองทางการต่อ shipment \n port clearance การตรวจ ณ ด่านของประเทศผู้นำเข้า \n บทบาทของสัตวแพทย์ 4 ด้าน \n farm health management วินิจฉัยโรค สั่งใช้ยาอย่างรับผิดชอบ และกำกับ withdrawal period \n audit และ certification ตรวจรับรองฟาร์มตาม gap หรือ coc และสนับสนุนการทวนสอบแผน haccp \n residue และ hazard oversight ให้คำแนะนำการใช้ยาต้านจุลชีพและ biocide เพื่อลดสารตกค้างและความเสี่ยง amr \n one health coordination ประสานงานข้ามด้านสุขภาพสัตว์ ความปลอดภัยอาหาร และสุขภาพสิ่งแวดล้อม \n สหภาพยุโรปบังคับใช้ข้อกำหนดผ่านการตรวจ ณ ด่านและระบบแจ้งเตือน rasff โดยประเภทการแจ้งมีทั้ง alert, information และ border rejection กลุ่มสินค้าที่ถูกแจ้งรวมถึงปลา หอย และ crustaceans และไทยเป็นหนึ่งในประเทศต้นทางของสินค้าที่ถูกแจ้ง ผลที่ตามมาคือสินค้าถูกส่งกลับ ไม่อนุญาตให้นำเข้า ถูกถอนออกจากตลาด ถูกทำลาย หรือถูกเรียกคืน \n อุตสาหกรรมประมงเผชิญกิจกรรมการทำประมงผิดกฎหมาย ขาดการรายงาน และไร้การควบคุม (iuu) ในระดับที่มีนัยสำคัญภายในระบบห่วงโซ่อุปทานแบบดั้งเดิม ซึ่งเป็นเหตุผลที่ระบบตรวจสอบย้อนกลับและเอกสารกำกับการจับถูกออกแบบมาเพื่อป้องกันและตรวจจับ iuu \n woah (world organisation for animal health) จัดทำ aquatic animal health code เป็นมาตรฐานสากลด้านสุขภาพสัตว์น้ำสำหรับการค้าระหว่างประเทศอย่างปลอดภัย ซึ่งรวมถึงแนวทางการออกใบรับรองสุขภาพ (health certificate) สำหรับสัตว์น้ำและผลิตภัณฑ์สัตว์น้ำ และบทบาทการกำหนดมาตรฐานของ woah ได้รับการรับรองอย่างเป็นทางการในความตกลง sps ขององค์การการค้าโลก']],'food-industry--fiqc-haccp':[['food-industry--fiqc-haccp--haccp-คืออะไร-และ-hazard-3-กลุ่ม','HACCP คืออะไร และ hazard 3 กลุ่ม','haccp คืออะไร และ hazard 3 กลุ่ม \n physical hazard: foreign body เช่น เส้นผม แหวน โลหะ พลาสติก หิน \n chemical hazard: ยาปฏิชีวนะ ยาฆ่าแมลง สารเคมีทางการเกษตร heavy metal \n biological hazard: pathogenic bacteria (salmonella, campylobacter, listeria, staphylococcus) รวมถึงไวรัสและเชื้อรา \n codex นิยาม hazard ว่าเป็น biological, chemical หรือ physical agent ในอาหารที่มีศักยภาพก่อผลเสียต่อสุขภาพ ซึ่งเป็นที่มาของการแบ่ง hazard เป็น 3 กลุ่มตามสไลด์ \n codex ระบุชื่อ salmonella และ campylobacter เป็นเชื้อก่อโรคทางอาหารหลักที่ต้องคุมด้วยการควบคุมการปนเปื้อนอุจจาระ ตรงกับ biological hazard ที่สไลด์ยกมา และ worksheet วิเคราะห์อันตรายของ codex ก็แบ่งช่องเป็น b (biological), c (chemical), p (physical)'],['food-industry--fiqc-haccp--ปิรามิดมาตรฐาน-food-safety-และ-gfsi','ปิรามิดมาตรฐาน food safety และ GFSI','ปิรามิดมาตรฐาน food safety และ gfsi \n ฐานปิรามิด: codex haccp principles + gmp/ghp = กฎหมายพื้นฐานของแต่ละประเทศ นิยมและเป็นพื้นฐานที่สุด \n legislation (food law) = ข้อกำหนดของประเทศนำเข้า เช่น ค่า mrl สารเคมี toxin \n iso standards (iso 22000) = มาตรฐานสากลแบบสมัครใจ ขึ้นกับผู้ซื้อ โดย iso ประกอบด้วย prp (prerequisite programme) + haccp \n gfsi recognised schemes = global food safety initiative ทำหน้าที่เป็น benchmark เทียบเคียงว่า scheme ต่างๆ (globalgap, fssc 22000, brc, ifs, sqf, primusgfs ฯลฯ) เหมาะเป็นมาตรฐาน food safety หรือไม่ บาง scheme รวม food quality ด้วย \n ยอดปิรามิด: best practice = มาตรฐานสูงสุด กำหนดโดยผู้ซื้อหรือกลุ่มผู้ซื้อ โดยเฉพาะ eu เช่น sustainability, carbon footprint \n codex เปลี่ยน gmp เป็น ghp ตั้งแต่ปี 2021 เพราะขอบเขตคือสุขลักษณะ (hygiene) ตลอดการผลิตรวมถึงระดับฟาร์มและงานที่ไม่ได้แปรรูปมาก (เช่น แค่แพ็คใส่ถุง) ไม่ใช่เฉพาะการผลิตในโรงงาน \n gfsi ทำหน้าที่ benchmark เจ้าของ scheme (certification programme owners) ว่าผ่านเกณฑ์หรือไม่ โดย scheme ที่ได้รับการรับรองรวมถึง brcgs, fssc 22000, ifs, sqf, globalg.a.p. และ primusgfs ตรงกับรายชื่อในสไลด์'],['food-industry--fiqc-haccp--กฎหมายอาหารของ-eu','กฎหมายอาหารของ EU','กฎหมายอาหารของ eu \n general food law = regulation 178/2002 กฎหมายแม่บทคุม food safety ตั้งแต่ปี 2002 (พัฒนามาจาก white paper) สินค้าส่งออกไป eu ต้องเป็นไปตามนี้ \n regulation 183/2005 = feed for animals \n regulation 852/2004 = all foodstuffs \n regulation 853/2004 = food of animal origin \n regulation 882/2004 = official controls (ร่วมกับ 854/2004) \n ครอบคลุมทั้ง animal health, animal welfare, compliance to feed law และ food law \n regulation (ec) no 178/2002 เป็นกฎหมายแม่บทที่วางหลักการและข้อกำหนดทั่วไปของ food law ของ eu จัดตั้ง efsa และกำหนด traceability ตาม article 18 ตรงกับที่สไลด์ระบุว่าเป็น general food law'],['food-industry--fiqc-haccp--food-safety-กับ-food-hygiene','Food safety กับ Food hygiene','food safety กับ food hygiene \n food safety = ความปลอดภัยของผลิตภัณฑ์ขั้นสุดท้าย ใช้ direct indicators เช่น no salmonella, no listeria, ไม่มีสารเคมีหรือยาต้องห้าม \n food hygiene = การควบคุมอันตรายระหว่างกระบวนการผลิต (ความสะอาด) ใช้ indirect indicators เช่น apc, enterococci, coliform \n indicator organisms เช่น e. coli มีอยู่ในสิ่งแวดล้อมอยู่แล้ว ค่าที่สูงบ่งชี้ความสกปรกของกระบวนการ ไม่ได้แปลว่าเป็นเชื้อก่อโรคเสมอไป \n codex แยกนิยาม food safety (การประกันว่าอาหารจะไม่ก่อผลเสียต่อสุขภาพผู้บริโภคเมื่อเตรียมหรือกินตามวัตถุประสงค์) ออกจาก food hygiene (เงื่อนไขและมาตรการทั้งหมดเพื่อประกันความปลอดภัยและความเหมาะสมของอาหารทุกขั้นตอนของห่วงโซ่) ตรงกับที่สไลด์แยกไว้ \n กฎหมาย eu แยกเกณฑ์จุลชีววิทยาเป็น food safety criterion (ตัดสินความยอมรับได้ของผลิตภัณฑ์หรือรุ่นที่วางตลาด) กับ process hygiene criterion (บ่งชี้ว่ากระบวนการผลิตทำงานในระดับที่ยอมรับได้ ไม่ใช้กับสินค้าที่วางตลาดแล้ว) ซึ่งเป็นฐานกฎหมายของการแยก direct indicator กับ indirect indicator ตามสไลด์'],['food-industry--fiqc-haccp--prerequisite-program-และ-5-primary-steps','Prerequisite program และ 5 primary steps','prerequisite program และ 5 primary steps \n without basic prerequisite (biosecurity / ghp / gap), hardly haccp successful จะทำ hazard plan ให้สำเร็จต้องมี pre-program ที่ดีก่อน และสิ่งแวดล้อมการผลิตต้องสะอาด \n primary 5 steps ต้องทำตามลำดับ: 1) ตั้งทีม haccp (ส่วนใหญ่เป็นคนในโรงงาน) 2) บรรยายผลิตภัณฑ์และ scope 3) ระบุกลุ่มผู้บริโภค 4) เขียน flow diagram 5) ตรวจ flow diagram ว่าตรงกับหน้างานจริงหรือไม่ \n codex ระบุตรงตัวว่า haccp จะไม่ได้ผลถ้าไม่ได้ทำ prerequisite programme รวมถึง ghps ก่อน ตรงกับข้อความ without basic prerequisite hardly haccp successful ในสไลด์ \n ลำดับ 5 ขั้นแรกของ codex คือ 1) assemble haccp team 2) describe product 3) identify intended use 4) construct flow diagram 5) on-site confirmation of flow diagram ตรงกับลำดับที่สไลด์ให้ท่อง (ทั้งหมดเป็นส่วนหนึ่งของ logic sequence 12 ขั้น)'],['food-industry--fiqc-haccp--principle-1-ชี้บ่งอันตรายและประเมินความเสี่ยง','Principle 1: ชี้บ่งอันตรายและประเมินความเสี่ยง','principle 1: ชี้บ่งอันตรายและประเมินความเสี่ยง \n ลำดับใน ccp analysis: เขียน process ทั้งหมด แล้วชี้บ่ง potential hazard ของแต่ละ process (ดูจากประวัติฟาร์ม) ประเมินระดับความเสี่ยง และระบุมาตรการควบคุมของทุกขั้นตอน \n risk = severity x likelihood of occurrence (severity อ้างงานวิจัย ส่วน likelihood ดูจากประวัติฟาร์ม) \n matrix แบ่งเป็น critical, major, minor, satisfactory โดย critical = severity สูง + likelihood สูง \n ระดับ severity: low = หายเองได้, medium = ป่วย, high = ตายได้ \n ตัวอย่าง control measures \n biological: bedding และ feed จากแหล่งที่เชื่อถือได้, cleaning program, day-old chick จากฝูง breeder ที่ salmonella negative, water treatment, personal hygiene, pest control, traffic control \n chemical: ระยะหยุดยาและยาฆ่าแมลงที่เพียงพอ, ใช้ยาตาม vet prescription เท่านั้น, approved chemical list, approve supplier (bedding, feed) \n physical: ระยะงดอาหารที่เพียงพอ และ training program \n principle 1 ของ codex คือทำ hazard analysis และระบุมาตรการควบคุม โดยนิยาม hazard analysis ว่าเป็นการรวบรวมและประเมินข้อมูลอันตรายจากวัตถุดิบ สิ่งแวดล้อม กระบวนการ และตัวอาหาร เพื่อตัดสินว่าเป็น significant hazard หรือไม่ ตรงกับที่สไลด์ให้ไล่ทุก process แล้วชี้บ่ง potential hazard \n codex กำหนดให้พิจารณา significance ของอันตรายจากโอกาสเกิดเมื่อไม่มีการควบคุม ร่วมกับความรุนแรงของผลกระทบ ตรงกับสูตร risk = severity x likelihood ที่สไลด์ใช้ และนิยาม significant hazard ก็ผูกกับความน่าจะเกิดในระดับที่ยอมรับไม่ได้'],['food-industry--fiqc-haccp--principle-2-หาจุด-ccp-ด้วย-decision-tree','Principle 2: หาจุด CCP ด้วย decision tree','principle 2: หาจุด ccp ด้วย decision tree \n ccp = จุดที่ต้องใช้มาตรการป้องกันเพื่อลด ป้องกัน หรือกำจัดอันตรายต่อความปลอดภัยของผลิตภัณฑ์ คุณสมบัติของ ccp ที่ดีคือ วัดได้หรือสังเกตได้ กำหนด tolerance limit ได้ และมีมาตรการแก้ไขเมื่อเบี่ยงเบน \n cp (control point) = จุดที่ความเสี่ยงต่ำ (not likely to occur) ส่วน ccp บ่งชี้ความเสี่ยงสูง (likely to occur) และกระบวนการหนึ่งอาจไม่มี ccp เลยก็ได้ \n codex ให้ใช้ decision tree 4 คำถามเป็น guideline ไม่จำเป็นต้องตอบครบทุกข้อ hazard team จึงต้องมีความรู้จริง \n decision tree (ฉบับเริ่มจากโปรแกรมพื้นฐาน) \n q1: ควบคุมอันตรายที่มีนัยสำคัญ ณ ขั้นตอนนี้ให้อยู่ในระดับยอมรับได้ด้วยโปรแกรมพื้นฐาน (เช่น ghps) ได้หรือไม่ ถ้าได้ = ไม่เป็น ccp หยุดได้เลย \n q2: ขั้นตอนนี้มีมาตรการควบคุมเฉพาะสำหรับอันตรายที่ระบุหรือไม่ (เช่น การใช้ chlorine) ถ้าไม่มี = ไม่เป็น ccp \n q3: ขั้นตอนต่อไปมีมาตรการป้องกัน ขจัด หรือลดอันตรายนี้ได้หรือไม่ (เช่น water treatment) ถ้ามี = ขั้นตอนต่อไปนั้นเป็น ccp \n q4: ขั้นตอนนี้เฉพาะเจาะจงในการป้องกัน ขจัด หรือลดอันตรายหรือไม่ ถ้าใช่ = เป็น ccp ถ้าไม่ใช่ = ปรับเปลี่ยนขั้นตอน กระบวนการ หรือผลิตภัณฑ์ \n อย่าท่องลำดับคำตอบของ tree เป็น pattern ให้เข้าใจว่าแต่ละคำถามถามอะไร แล้วไล่เหตุผลจนสรุปได้ว่าจุดใดเป็น ccp \n codex นิยาม ccp ว่าเป็นขั้นตอนที่ใช้มาตรการควบคุมซึ่งจำเป็นต่อการควบคุม significant hazard และเน้นว่า critical limit ต้องวัดได้หรือสังเกตได้ ตรงกับคุณสมบัติ ccp ที่ดีตามสไลด์ \n คำถาม 4 ข้อของ decision tree ใน codex ตรงกับที่สไลด์สรุป โดย q1 ถามว่าคุมด้วย prerequisite programme (เช่น ghps) ได้ไหม ถ้าได้ขั้นตอนนั้นไม่เป็น ccp, q2 ถามว่ามีมาตรการควบคุมเฉพาะที่ขั้นตอนนี้ไหม, q3 ถามว่าขั้นตอนถัดไปจัดการได้ไหม (ถ้าได้ ขั้นตอนถัดไปเป็น ccp), q4 ถามว่าขั้นตอนนี้ป้องกัน ขจัด หรือลดอันตรายได้เฉพาะเจาะจงไหม ถ้าใช่คือ ccp ถ้าไม่ใช่ต้องปรับขั้นตอนหรือผลิตภัณฑ์ \n codex ระบุว่า decision tree เป็นเพียงตัวอย่างเครื่องมือ ไม่ใช่วิธีเดียว ใช้เครื่องมืออื่นได้ตราบใดที่ยังทำตามข้อกำหนดของ step 7 principle 2 ได้ครบ สนับสนุนที่สไลด์บอกว่าให้ใช้เป็น guideline และไม่ต้องท่องลำดับคำตอบ'],['food-industry--fiqc-haccp--principle-3-critical-limit-และ-operating-limit','Principle 3: Critical Limit และ Operating Limit','principle 3: critical limit และ operating limit \n cl = เส้นแบ่งระดับที่ยอมรับได้กับยอมรับไม่ได้ ตามความปลอดภัยของอาหาร \n คุณสมบัติ cl: วัดค่าได้ ได้รับการพิสูจน์ (validated) โดยโรงงานเอง ผู้อื่นทดสอบ หรือกฎหมายระบุ และ กำหนดเป็นตัวเลขหรือคำบรรยายก็ได้ \n ที่มาของ cl: กฎหมายและข้อบังคับ, industry thresholds, ข้อกำหนดลูกค้า, ข้อมูลอื่นที่เกี่ยวข้อง \n cl เป็นเลขเดียวกับ operating limit (ol) ได้ \n ตัวอย่าง pasteurizer \n cl = 160 f: หลุดค่านี้ต้องทำ corrective action กับผลิตภัณฑ์ \n ol (minimal) = 165 f: ค่าที่ตั้งเผื่อไว้ก่อนถึง cl ถ้าหลุด ol แต่ยังไม่ต่ำกว่า cl สินค้ายังปลอดภัย เป็นสัญญาณให้ปรับกระบวนการหรือตรวจเครื่องจักร \n codex นิยาม critical limit ว่าเป็นเกณฑ์ที่สังเกตได้หรือวัดได้ ซึ่งแยกความยอมรับได้ออกจากความยอมรับไม่ได้ของอาหาร และระบุตัวอย่างทั้งแบบวัดค่า (เวลา อุณหภูมิ ph aw) และแบบสังเกต (ความเร็วสายพาน ตำแหน่งปั๊ม การกลบน้ำแข็ง) ตรงกับที่สไลด์บอกว่าเป็นตัวเลขหรือคำบรรยายก็ได้ \n codex กำหนดว่า critical limit ต้องผ่าน validation ในระหว่างจัดทำแผน haccp โดยอาศัยวรรณกรรมวิทยาศาสตร์ แบบจำลองทางคณิตศาสตร์ การทดลอง validation หรือแนวทางจากหน่วยงานที่เชื่อถือได้ ตรงกับที่สไลด์บอกว่า cl ต้องได้รับการพิสูจน์จากโรงงานเอง ผู้อื่น หรือกฎหมาย'],['food-industry--fiqc-haccp--principles-4-7-monitoring-corrective-action-verification-record-','Principles 4-7: monitoring, corrective action, verification, record keeping','principles 4-7: monitoring, corrective action, verification, record keeping \n p4 monitoring (เฝ้าระวัง ccp) \n p5 corrective action \n p6 verification (ทวนสอบ) \n p7 record keeping \n principle 4 ถึง 7 ของ codex คือ ตั้งระบบ monitor การควบคุม ccp, กำหนด corrective action เมื่อ monitoring พบการเบี่ยงเบนจาก critical limit ที่ ccp, validate แผนแล้วตั้งขั้นตอน verification เพื่อยืนยันว่าระบบทำงานตามที่ตั้งใจ และจัดทำเอกสารกับบันทึกให้ครบ ตรงกับที่สไลด์ไล่ p4 ถึง p7 \n codex กำหนดให้ corrective action จัดการทั้งตัวผลิตภัณฑ์ (แยกออกมาและตัดสิน disposition เช่น reprocess, divert หรือทำลาย) และหาสาเหตุรากเพื่อแก้กระบวนการไม่ให้เกิดซ้ำ สอดคล้องกับแนว 3p (product, process, people) ที่สไลด์ใช้ รวมถึงตัวอย่างนมที่ต้องนำไป re-process \n verification ตาม codex ครอบคลุมทั้งระบบไม่ใช่เฉพาะจุด ccp ได้แก่ ทบทวนบันทึก monitoring และ corrective action, calibration เครื่องมือวัด, การสุ่มตรวจผลิตภัณฑ์และสิ่งแวดล้อม (เช่น listeria), และ internal หรือ third-party audit และต้องทำโดยคนอื่นที่ไม่ใช่ผู้ทำ monitoring ตรงกับรายการ verification ในสไลด์'],['food-industry--fiqc-haccp--ตัวอย่าง-ccp-ระดับฟาร์มไก่เนื้อ','ตัวอย่าง CCP ระดับฟาร์มไก่เนื้อ','ตัวอย่าง ccp ระดับฟาร์มไก่เนื้อ \n การล้างฆ่าเชื้อโรงเรือนและวัสดุรองพื้น (c&d): cl = ทำตาม procedure และ swab แล้ว salmonella negative \n การรับ doc: cl = ฝูง salmonella และ campylobacter negative ตรวจจาก coa (certificate of analysis) เมื่อส่งมอบ \n การรับอาหาร: salmonella negative และไม่ใช้ยาต้องห้าม ยืนยันด้วย coa หรือ letter of guarantee \n boot swab: ถ้าฝูมบวก แจ้งโรงเชือด วางแผนเชือดท้ายวัน และ deep c&d จนผลลบก่อนลงฝูงใหม่ \n feed withdrawal: ลดอาหารค้างในทางเดินอาหาร (physical hazard) \n antibiotic และ insecticide withdrawal: ยึด vpom (vet prescription of medication) และ withdrawal period ตรวจจาก treatment record ถ้าไม่ผ่านให้เลื่อนแผนเชือดหรือจัดการเป็น nc product \n eu กำหนด union target ให้ลดฝูงไก่เนื้อที่ผลบวก salmonella enteritidis และ typhimurium เหลือไม่เกิน 1 เปอร์เซ็นต์ต่อปี โดยเก็บตัวอย่างด้วย boot swab ในฝูงก่อนส่งเชือด สนับสนุนการใช้ boot swab เป็นเกณฑ์ควบคุมระดับฟาร์มตามสไลด์ \n crop เป็นแหล่งปนเปื้อน salmonella และ campylobacter ที่สำคัญของซากในโรงเชือด และการแทรกแซงระหว่างช่วง feed withdrawal (ให้ lactic acid ในน้ำ) ลด salmonella ใน crop และในน้ำล้างซากก่อน chilling ได้อย่างมีนัยสำคัญ สนับสนุนการวาง feed withdrawal เป็นจุดควบคุมระดับฟาร์ม'],['food-industry--fiqc-haccp--ตัวอย่าง-ccp-ในโรงเชือดและโรงงานแปรรูป','ตัวอย่าง CCP ในโรงเชือดและโรงงานแปรรูป','ตัวอย่าง ccp ในโรงเชือดและโรงงานแปรรูป \n จุดที่เอกสารเน้นซ้ำ: จุดล้างซาก และ chilling ถูกกำหนดเป็น ccp \n รับไก่เข้าเชือด: ฝูง salmonella negative (boot swab), feed withdrawal record, drug และ pesticide withdrawal (ตรวจตัวไก่ด้วย microassay หายา ตรวจไขมันหา pesticide residue) \n ล้างซาก inside-outside: คุม water pressure และ water volume (มีมิเตอร์วัด) กันการปนเปื้อน salmonella ดิน เศษอาหาร \n water chiller: cl = core temp ซากไม่เกิน 4 c (จาก ~30 c ภายใน ~45 นาที) พร้อม overflow น้ำ ตรวจด้วย probe เสียบอกไก่ โดย usa อนุญาต chlorine ใน chiller แต่ eu ไม่ยอมรับ \n boneless product packing: cl = no bone ตรวจ manual checking และ x-ray \n metal detection ในสไลด์ตัวอย่าง: cl = fe 2 mm, non-fe 2.5 mm, ss 3.5 mm (requirement แต่ละที่ต่างกันได้) \n ตัวเลขจริงจากโรงงานไทย (frozen chicken meat preparations) \n ccp1b ล้างซาก: water consumption อย่างน้อย 1.5 ลิตรต่อซาก \n ccp2b1 chilling: core temp carcass ไม่เกิน 4 c และ ccp2b2 overflow อย่างน้อย 2.5 ลิตรต่อซาก \n ccp3p metal detecting: fe 2.5 mm, non-fe 3.5 mm, sus 4.5 mm เครื่องต้องร้องเตือนเมื่อจับได้ \n จุดผสมและกรองผงหมัก (ccp3p): ต้องไม่พบสิ่งแปลกปลอมใหญ่กว่ารูตะแกรง 10, 20, 25, 30 mesh ตาม spec \n กฎหมาย eu กำหนดว่าหลังตรวจซากและควักเครื่องในแล้ว ต้องทำความสะอาดและลดอุณหภูมิซากให้ไม่เกิน 4 องศาเซลเซียสโดยเร็วที่สุด ตรงกับ critical limit ของขั้น chilling ที่สไลด์กำหนดว่า core temp ไม่เกิน 4 องศาเซลเซียส \n เหตุที่ eu ไม่ยอมรับ chlorine ในน้ำ chiller ขณะที่ usa อนุญาต มาจากข้อกำหนดที่ห้ามใช้สารอื่นนอกจาก potable water เพื่อกำจัดการปนเปื้อนที่ผิวสินค้าปศุสัตว์ เว้นแต่ commission จะอนุมัติสารนั้น ตรงกับที่สไลด์ระบุ'],['food-industry--fiqc-haccp--มาตรการควบคุมระดับฟาร์มของไก่ไทย-ภาพรวม','มาตรการควบคุมระดับฟาร์มของไก่ไทย (ภาพรวม)','มาตรการควบคุมระดับฟาร์มของไก่ไทย (ภาพรวม) \n biological (salmonella, campylobacter): ghp, haccp, iso9001 ร่วมกับ dld gap, global gap, farmf1rst โดยทำ vaccination ในฝูง breeder + lab testing (swab หลังล้างเล้า และ boot swab ก่อนเชือด) \n chemical (drug, pesticide, heavy metal): withdrawal, ควบคุมโลหะหนักในอาหารและน้ำ, ตรวจ drug และ insecticide residue ก่อนเชือด รวมถึงโปรแกรม rwa (raised without antibiotics) และ alo \n physical (soil และ feed content): feed withdrawal ก่อนจับ \n codex กำหนดที่ระดับ primary production ให้ควบคุมสุขภาพสัตว์ไม่ให้เป็นภัยต่อคนผ่านอาหาร โดยยกตัวอย่างการยึดระยะหยุดยา (withdrawal period) ของยาสัตว์และสารกำจัดศัตรูพืชพร้อมเก็บบันทึก ตรงกับมาตรการ chemical hazard ที่สไลด์ระบุ \n codex ระบุว่า ghps และ gaps เป็น prerequisite programme ที่ลดโอกาสและระดับอันตรายตั้งแต่ระดับฟาร์ม รวมถึงการควบคุมการปนเปื้อนจากดิน น้ำ อาหารสัตว์ ปุ๋ย และยาสัตว์ ตรงกับที่สไลด์ผูก ghp กับ haccp และ gap เข้าด้วยกันที่ระดับฟาร์ม']],'food-industry--fiqc-poultry-export':[['food-industry--fiqc-poultry-export--ภาพรวมการส่งออกไก่ไทย','ภาพรวมการส่งออกไก่ไทย','ภาพรวมการส่งออกไก่ไทย \n ไทยส่งออก เนื้อไก่ปรุงสุก (cooked) มากกว่าไก่ดิบ (raw) ตั้งแต่ ai ระบาด ตลาดเนื้อดิบถูกจำกัด สินค้าปรุงสุกจึงโต \n ตลาดไก่ดิบ: ญี่ปุ่นอันดับ 1 ตามด้วยไก่หมักเกลือไป eu, มาเลเซีย, asean, จีน-ฮ่องกง \n ตลาดไก่ปรุงสุก: ญี่ปุ่นอันดับ 1 ตามด้วย eu, uk, เกาหลี \n คู่แข่งหลักคือ บราซิล แต่ค่าแรงของเขาสูงขึ้น และไทยปรับสินค้าตามใจลูกค้าได้ดีกว่า \n โรงงานส่งออกต้องมี เลข est ที่รับรองโดยกรมปศุสัตว์ และเลขจะอยู่ตลอดไป \n ไก่หมักเกลือ: eu จัดประเภทเป็น cooked แต่ไทยถือว่าเป็น raw \n โดยปริมาณ สินค้าไก่แปรรูป (ปรุงสุก) เป็นสัดส่วนใหญ่ของการส่งออกไก่ไทย มากกว่าไก่แช่แข็ง (ดิบ) ตรงกับที่สไลด์ระบุว่าไทยส่งออกเนื้อไก่ปรุงสุกมากกว่าไก่ดิบ \n ญี่ปุ่นเป็นตลาดอันดับ 1 ทั้งของไก่ปรุงสุกและไก่แช่แข็งของไทย โดยกินสัดส่วนราว 47.7 เปอร์เซ็นต์ของไก่แปรรูป และ 38.4 เปอร์เซ็นต์ของไก่แช่แข็ง ตรงกับที่สไลด์ระบุว่าญี่ปุ่นอันดับ 1 ทั้งสองตลาด'],['food-industry--fiqc-poultry-export--eu-quota-และกำแพงภาษี','EU quota และกำแพงภาษี','eu quota และกำแพงภาษี \n eu ตั้ง โควตานำเข้า เป็นกำแพงภาษีเพื่อรักษาดุลผู้ผลิตในประเทศ \n ภาษีในโควตา: ไก่หมักเกลือ 15.4% และ ไก่ปรุงสุก 8% \n นอกโควตา: จ่ายแบบต่อหน่วยซึ่งแพงกว่า คือ 1,300 euro ต่อตัน (หมักเกลือ) และ 1,024 euro ต่อตัน (ไก่สุก) \n ตัวเลขภาษีตามสไลด์ตรงกับข้อตกลง trq ระหว่าง eu กับไทย คือ ไก่ปรุงสุกในโควตา 8 เปอร์เซ็นต์ ad valorem นอกโควตา 1,024 ยูโรต่อตัน ส่วนไก่หมักเกลือในโควตา 15.4 เปอร์เซ็นต์ ad valorem นอกโควตา 1,300 ยูโรต่อตัน'],['food-industry--fiqc-poultry-export--แนวโน้มการส่งออก-หลังโควิดและปีล่าสุด','แนวโน้มการส่งออก: หลังโควิดและปีล่าสุด','แนวโน้มการส่งออก: หลังโควิดและปีล่าสุด \n สไลด์รุ่นก่อน (แนวโน้มหลังโควิด) \n คาดว่าการส่งออกจะกลับมา ราคาเนื้อไก่สูงขึ้นมาก ค่าเงินอ่อนลงบ้าง แรงงานโรงแปรรูปกลับมาเกือบปกติ \n sea freight ยุโรปจาก 30-35 วัน เป็น 40-46 วัน \n ค่าระวางตู้ ยุโรป +480% (2,500 เป็น 12,000+ usd ต่อตู้ 24 mt เส้น rotterdam/felixstowe) และ ญี่ปุ่น +300% (1,200 เป็น 3,500 usd) \n ความเสี่ยง: เงินเฟ้อ รัฐควบคุมราคาเนื้อไก่ โรคไก่ ราคาวัตถุดิบอาหารสัตว์ สงคราม ukraine กับ russia \n ผู้สรุป (vet 85) ระบุว่าปีของเขาไม่มีสไลด์หลังโควิดแล้ว ถูกแทนด้วยสไลด์แนวโน้มชุดใหม่ ตัวเลขค่าระวางจึงเป็นบริบทของรุ่นก่อน ควรยึดสไลด์ปีปัจจุบัน \n สไลด์ปีของผู้สรุป (แนวโน้มส่งออก) \n ปัจจัยลบ: โรคระบาดไก่ (เช่น ai), ราคาวัตถุดิบอาหารสัตว์ (ไทยผลิตข้าวโพดและกากถั่วได้น้อย ต้องนำเข้า ต้นทุนสูง เสียเปรียบเรื่องค่าอาหาร), ukraine กับ russia (ยูเครนเป็นแหล่งข้าวโพด), แรงกดดันจากผู้ประกอบการฟาร์มในยุโรป (เพราะสินค้าไทยถูกกว่า), กฎหมาย esg ในยุโรปที่ผูกกับอัตราภาษี (เช่น carbon footprint ต่อชิ้นสินค้า) \n ปัจจัยบวก: ค่าเงินอ่อนลงบ้าง (แลกเงินไทยได้สูงขึ้น) และ นักท่องเที่ยวน่าจะมากขึ้น (การบริโภคสูงขึ้น) \n ยูเครนเป็นผู้ส่งออกข้าวโพดรายใหญ่อันดับ 4 ของโลก มีสัดส่วนราว 15 เปอร์เซ็นต์ของการส่งออกข้าวโพดโลก และสงครามทำให้การส่งออกหยุดชะงักจนราคาธัญพืชอาหารสัตว์พุ่งขึ้น สนับสนุนที่สไลด์ระบุว่าสงคราม ukraine กับ russia เป็นปัจจัยลบผ่านราคาวัตถุดิบอาหารสัตว์'],['food-industry--fiqc-poultry-export--ข้อกำหนดบังคับของกรมปศุสัตว์-thai-dld','ข้อกำหนดบังคับของกรมปศุสัตว์ (Thai DLD)','ข้อกำหนดบังคับของกรมปศุสัตว์ (thai dld) \n mandatory: haccp และ ghp certificate (dld), dld gap farm certificate สำหรับฟาร์มที่ส่งออก, free from ai และ nd หรือ compartment certificate \n no prohibited antibiotic (เกณฑ์ residue อ้าง codex และ eu regulation), no insecticide residue และ no heavy metal residue (อ้าง eu regulation) \n น้ำและน้ำแข็ง: mpn coliforms, e. coli, clostridium perfringens, enterococci ต้อง ไม่พบ (n) \n อุณหภูมิ: chilling carcass ต่ำกว่า 4 c, cutting room ต่ำกว่า 12 c, cold store ต่ำกว่า -18 c, frozen room ต่ำกว่า -25 c \n อ้างอิงประกาศกรมปศุสัตว์ เรื่องเกณฑ์ด้านจุลชีววิทยาของสินค้าปศุสัตว์เพื่อการส่งออก พ.ศ. 2551 \n เอกสารกาชัดว่า iso 14000 ไม่เกี่ยว เพราะเป็นมาตรฐานสิ่งแวดล้อม ไม่ใช่ food safety scheme \n เกณฑ์อุณหภูมิที่ dld ใช้ตรงกับกฎหมาย eu คือ ระหว่างตัดแต่ง ตัดกระดูก และบรรจุ ต้องคุมอุณหภูมิเนื้อไม่เกิน 4 องศาเซลเซียส โดยใช้อุณหภูมิห้องไม่เกิน 12 องศาเซลเซียส \n เกณฑ์ cold store ต่ำกว่า -18 องศาเซลเซียสมีฐานจากกฎหมายอาหารแช่เยือกแข็ง ซึ่งกำหนดให้สินค้า quick-frozen ต้องคงอุณหภูมิที่ทุกจุดของผลิตภัณฑ์ที่ -18 องศาเซลเซียสหรือต่ำกว่า ยอมให้แกว่งขึ้นชั่วคราวไม่เกิน 3 องศาระหว่างขนส่งและกระจายสินค้า'],['food-industry--fiqc-poultry-export--ข้อกำหนดรายประเทศ-จุดต่างที่ควรจำ','ข้อกำหนดรายประเทศ (จุดต่างที่ควรจำ)','ข้อกำหนดรายประเทศ (จุดต่างที่ควรจำ) \n europe: เกณฑ์คล้ายกรมปศุสัตว์ เนื้อดิบเน้น salmonella typhimurium และ enteritidis (n=5, c=0 ใน 25 g) กับ listeria monocytogenes อ้าง commission regulation (ec) 2073/2005 และฉบับแก้ไข \n uae และ gcc (saudi, kuwait, oman, uae, qatar, bahrain): เน้น shigella spp. และ halal certificate (เชือดด้วยมือขวาพร้อมกล่าวนามพระเจ้า ห้ามลับมีดต่อหน้าสัตว์ สัตว์ต้องได้พักก่อนเชือด) โดย ซาอุดีอาระเบียไม่ยอมรับ electrical stunning ในสัตว์ปีก (โน้ตระบุว่าเชือดสดทำให้เสียหายมาก) \n south africa: e. coli o157:h7 (ตารางเน้น salmonella enteritidis และ typhi ด้วย) \n singapore: salmonella typhi, paratyphi, enteritidis และ vtec สินค้าต้อง ปลอด ai (ฟาร์มตรวจด้วย egg inoculation หรือ rt-pcr) ส่วนไข่ต้องมาจาก ฟาร์ม gap ที่หน่วยงานของสิงคโปร์ (sfa) รับรอง, ไข่ 1 ฟาร์มต่อ 1 ตู้, ปลอด hpai/lpai (h5, h7) อย่างน้อย 3 เดือน, ปลอด nd/mg/ms/ilt/ibd/salmonella/ib อย่างน้อย 3 เดือน และมีโปรแกรมคุม s. enteritidis (เพราะบางคนกินไข่ดิบ) \n south korea: vibrio parahemolyticus และ e. coli o157:h7 ฟาร์มปลอด bursal disease (ibd) และ marek อย่างน้อย 1 ปี ไม่มี lpai หรือ nd ในรัศมี 10 km ตรวจ antigen ai (h5/h7) และ nd ที่โรงเชือด อย่างน้อย 60 ตัวต่อฟาร์ม จากอย่างน้อย 20% ของฟาร์มที่เชือด สินค้าผ่านความร้อน 70 c อย่างน้อย 30 นาที หรือ 75 c อย่างน้อย 5 นาที หรือ 80 c อย่างน้อย 1 นาที แล้วทำให้เย็นต่ำกว่า 5 c \n malaysia: halal certification โดย audit ปีละ 2 ครั้ง (มิถุนายน และธันวาคม) เกณฑ์จุลชีววิทยาเป็นแบบปริมาณที่ยอมรับได้ ไม่ใช่ n ทั้งหมด \n hong kong: no growth hormone ใช้เกณฑ์ ready-to-eat เพิ่ม campylobacter jejuni และ coli, vibrio parahemolyticus, e. coli o157:h7, shigella \n canada: สินค้าปรุงสุกตรวจ salmonella และ listeria monocytogenes = n (sfcr) \n russia: ปลอด ornithosis (psittacosis) มาจากฟาร์มปลอด salmonellosis ไม่ใช้ growth hormone และจำกัด radionuclides cs-137 กับ sr-90 \n china: freezing ต่ำกว่า -28 c และ frozen products core temp ต่ำกว่า -15 c ภายใน 48 ชั่วโมง มี list โรงงานที่จีน approve ตรวจ salmonella 5 ตัวอย่างต่อสัปดาห์ต่อเนื่อง 10 สัปดาห์ \n japan: heat processing core temp อย่างน้อย 70 c นาน 1 นาที ปลอด fowl cholera และ salmonellosis (เฉพาะ s. pullorum และ s. gallinarum) ตรวจ e. coli, clostridium perfringens, staph aureus, salmonella ตามชนิดสินค้า \n vietnam: เน้น salmonella = n ตาม circular 29/2010/tt-bnnptnt \n philippines: ใช้ iso 22000 certificate \n เกณฑ์ eu สำหรับเนื้อสัตว์ปีกสดตรงกับสไลด์ คือ salmonella typhimurium และ salmonella enteritidis แผนการสุ่ม n=5, c=0 ต้องตรวจไม่พบใน 25 กรัม ใช้วิธี en iso 6579-1 ร่วมกับ white-kauffmann-le minor scheme สำหรับ serotyping \n ข้อกำหนดผ่านความร้อนของประเทศผู้นำเข้า (เช่น ญี่ปุ่นและเกาหลี) อิงเกณฑ์การทำลายเชื้อ hpai ของ woah ซึ่งกำหนด core temperature 70 องศาเซลเซียสนาน 3.5 วินาที หรือ 60 องศาเซลเซียสนาน 507 วินาที ดังนั้นเกณฑ์ 70 องศาขึ้นไปตามสไลด์เป็นเกณฑ์ที่เข้มกว่ามาตรฐานขั้นต่ำสากล'],['food-industry--fiqc-poultry-export--animal-welfare-5-freedoms-5-domains-3s-และ-oie','Animal welfare: 5 Freedoms, 5 Domains, 3S และ OIE','animal welfare: 5 freedoms, 5 domains, 3s และ oie \n five freedoms (ใช้ฝั่ง eu, uk): from hunger and thirst, from discomfort, from pain injury and disease, to express normal behavior, from fear and distress \n five domains (ออสเตรเลีย): nutrition, environment, health, behavior, mental state \n 3s (french concept): suppress (เลี่ยงหรือเลิกทำ), substitute (ใช้วิธีอื่นแทน), soothe (บรรเทาให้เจ็บน้อยที่สุด) ใช้กับ mutilations เช่น tail docking, dehorning, hot-iron branding, castration, debeaking (ในไก่มีการตัดปาก จี้เดือยนิ้วที่ 5 ในตัวผู้ และตัดนิ้วที่ 4 เป็น label สายพันธุ์ตัวผู้) \n oie animal welfare ถูกยกเป็นข้อกำหนดที่ audit ได้ผ่าน iso/ts 34700 (2019) มี 11 ข้อ สอดคล้องกับ 5 freedoms อิง terrestrial animal health code บทที่ 7.1 \n five domains model ฉบับปี 2020 ประกอบด้วย 1 nutrition, 2 physical environment, 3 health, 4 behavioural interactions และ 5 mental state โดยโดเมนที่ 4 ถูกเปลี่ยนชื่อจาก behaviour เป็น behavioural interactions ซึ่งครอบคลุมปฏิสัมพันธ์กับสิ่งแวดล้อม สัตว์อื่น และมนุษย์ \n woah (oie) อ้าง five freedoms ไว้ใน terrestrial animal health code บทที่ 7.1 เป็นหลักการนำทางด้านสวัสดิภาพสัตว์ ตรงกับที่สไลด์ผูก oie เข้ากับ 5 freedoms และบทที่ 7.1'],['food-industry--fiqc-poultry-export--มาตรฐานและ-scheme-สวัสดิภาพของสัตว์ปีก','มาตรฐานและ scheme สวัสดิภาพของสัตว์ปีก','มาตรฐานและ scheme สวัสดิภาพของสัตว์ปีก \n มาตรฐานสัตว์ปีกยุคนี้ = food safety + animal welfare + sustainability (รวม worker welfare, สิ่งแวดล้อม, csr) \n ฝั่งที่สินค้าไทยใช้อยู่: genesis, globalgap, farm first (ระดับ silver, gold, platinum), qs และมาตรฐานลูกค้า (mcdonald\'s, kfc, migros) \n ฝั่ง inter ที่ ไทยยังไม่ได้การรับรอง: tierwohl (เยอรมนี), red tractor (uk), rspca (uk), soil association (uk), label rouge (ฝรั่งเศส), global animal partnership (us), better chicken commitment (eu, us) \n gap ไทยกำหนดความหนาแน่นไม่เกิน 39 kg ต่อตารางเมตร \n farm first คือ scheme ไทยที่ใช้ส่งออก eu ครอบคลุม integrity และ traceability, competency ของ staff, bird welfare and health, medicines and biosecurity, water and feed, vermin control, housing, environmental protection, catching-transport-lairage-slaughter และ social standard (อ้าง smeta/sedex ethical trade audit) \n ตัวเลขจาก matrix เทียบมาตรฐาน \n ความหนาแน่น (kg ต่อตารางเมตร): กฎหมาย eu/uk 42/39, tierwohl 35, red tractor indoor 38, rspca indoor 30-34, free range 27.5, organic uk 21-30 \n ยิ่งระดับ welfare สูง: ความหนาแน่นลด ใช้พันธุ์โตช้า มีของเล่น มีแสงธรรมชาติและช่วงมืด มีพื้นที่นอกเล้า \n kfc มี animal wellness haccp พร้อม welfare target และ report ส่วน yum (kfc, pizza) ประเมิน ccp ในแง่ welfare เอง \n ตัวชี้วัด welfare หลังฆ่า เช่น pododermatitis, hock burn, doa, เปอร์เซ็นต์ตายและคัดทิ้ง ใช้ย้อนดูสวัสดิภาพในฟาร์ม (assurewel ประเมินทั้งระดับฝูง เดินสุ่ม 20% และรายตัว) \n เปรียบเทียบ us ncc, canada, gap (ตัวอย่างเกณฑ์) \n ammonia: us 25 ppm, canada 25 ppm และความชื้นไม่เกิน 70%, gap 20 ppm \n stocking density: canada 31 kg ต่อตารางเมตร (เงื่อนไขพิเศษถึง 38), gap ไล่ระดับราว 27-32 พร้อมจำกัดขนาดกลุ่ม 2,000 ตัว \n งดอาหารก่อนจับ: us ไม่เกิน 18 ชั่วโมง, canada อย่างน้อย 3 แต่ไม่เกิน 6 ชั่วโมง, gap ไม่เกิน 12 ชั่วโมง \n catch to kill: us ไม่เกิน 12 ชั่วโมง และ doa ไม่เกิน 0.5% \n effective stunning ประเมินจาก 500 ตัว และ gap ตั้งแต่ปี 2024 กำหนด level 2 ขึ้นไปต้องใช้ไก่โตช้า ส่วน level 5+ คือใช้ชีวิตทั้งหมดในฟาร์ม (รถเชือดเข้าฟาร์ม) \n วิธีทำสลบตามโน้ตกำกับ: us ใช้แก๊ส, ไทยใช้ไฟฟ้า (สอดคล้อง halal), eu ใช้ทั้งแก๊สและไฟฟ้า \n ระยะพักเล้าตามโน้ต: ไทยราว 21+3 = 24 วัน ถ้าได้ compartment อาจเหลือราว 14+3 = 17 วัน \n beter leven และ hubbard chicken of tomorrow \n beter leven (เนเธอร์แลนด์): 1 ดาว = 56 วัน เลี้ยงในโรงเรือนพร้อม winter garden (covered range), 2 ดาว = 56 วัน free range, 3 ดาว = มากกว่า 70 วัน free range ขนาดใหญ่ (organic นับรวมในกลุ่มนี้) ส่วนมากทำได้ระดับ 1 ดาว \n ตาราง hubbard: conventional = พันธุ์โตเร็ว 42 kg ต่อตารางเมตร เชือด 35-42 วัน ไม่มี enrichment ทำสลบ electrical + 2-phase co2 ขณะที่กลุ่ม 56-day + wintergarden (1 ดาว) = โตช้า adg ราว 42 g ต่อวัน อย่างน้อย 56 วัน 25 kg ต่อตารางเมตร มีฟางและเมล็ดพืช wintergarden 20-25% แสงธรรมชาติอย่างน้อย 20 lux มืด 8 ชั่วโมง และ ทำสลบด้วยแก๊สเท่านั้น (2-phase co2) \n red tractor มี 3 ระดับ (certified standards, enhanced welfare ที่ใช้พันธุ์โตช้าและพื้นที่เพิ่ม 29%, free range) พร้อมมาตรฐานเครื่องจับไก่อัตโนมัติและ hof (hatch on farm) \n กฎหมายสวัสดิภาพไก่เนื้อของ eu กำหนดความหนาแน่นสูงสุด 33 กิโลกรัมต่อตารางเมตรเป็นค่าพื้นฐาน ขยับเป็น 39 ได้เมื่อทำตามข้อกำหนดสิ่งแวดล้อมเพิ่มเติม และ 42 ได้เมื่ออัตราตายสะสมต่ำ ดังนั้นตัวเลข 42/39 ในตารางของสไลด์คือเพดานสูงสุดแบบมีเงื่อนไข ไม่ใช่ค่าปกติของกฎหมาย \n เกณฑ์คุณภาพอากาศในโรงเรือนไก่เนื้อตามกฎหมาย eu คือ nh3 ไม่เกิน 20 ppm และ co2 ไม่เกิน 3,000 ppm วัดที่ระดับหัวไก่ ซึ่งเป็นตัวเลขอ้างอิงเดียวกับที่ scheme สวัสดิภาพต่างๆ ใช้'],['food-industry--fiqc-poultry-export--better-chicken-commitment-bcc','Better Chicken Commitment (BCC)','better chicken commitment (bcc) \n 1) สอดคล้องกฎหมายด้านสวัสดิภาพสัตว์ \n 2) ความหนาแน่นไม่เกิน 30 kg ต่อตารางเมตร และ thinning (ล้วงไก่บางส่วน) ไม่เกิน 1 ครั้งต่อรุ่น \n 3) ใช้ สายพันธุ์โตช้าที่ให้ผลลัพธ์ welfare ดีขึ้น: hubbard ja757, 787, 957, 987, redbro, rambler ranger, ranger classic, ranger gold, label rouge หรือพันธุ์ที่ผ่าน rspca broiler breed welfare assessment protocol หรือ ecc/eu (โน้ตระบุว่าไทยยังไม่มีพันธุ์เหล่านี้ ต้องเอามาจาก eu) \n 4) environmental enrichment: แสงอย่างน้อย 50 lux รวมถึงมีแสงธรรมชาติ, คอนอย่างน้อย 2 เมตร และของจิกเล่นอย่างน้อย 2 ชิ้นต่อไก่ 1,000 ตัว, คุณภาพอากาศ nh3 ไม่เกิน 20 ppm, และ ห้ามเลี้ยงในกรงหรือระบบกรงแบบกว้างเป็นชั้น \n 5) ทำสลบด้วย cas (controlled atmospheric stunning) ใช้ inert gas หรือ multi-phase systems หรือใช้กระแสไฟฟ้าที่มีประสิทธิภาพโดย ไม่แขวนขาไก่ขณะยังมีความรู้สึก (โน้ตระบุว่าไทยยังทำไม่ได้ เพราะตลาด halal ไม่ยอมรับ) \n 6) audit โดย third party และรายงานความคืบหน้า bcc ประจำปี \n เกณฑ์อากาศในเอกสารพิมพ์ว่า co ไม่เกิน 3,000 ppm ซึ่งตามเกณฑ์ bcc สากลตัวเลขนี้เป็นของ co2 ควรตรวจกับสไลด์ปีปัจจุบันก่อนใช้ตัวเลขนี้ \n เกณฑ์ bcc ตรงกับที่สไลด์ระบุ คือ ความหนาแน่นไม่เกิน 30 กิโลกรัมต่อตารางเมตร thinning ไม่เกิน 1 ครั้งต่อรุ่น แสงอย่างน้อย 50 lux รวมแสงธรรมชาติ คอนใช้งานได้อย่างน้อย 2 เมตรและวัสดุให้จิก 2 ชิ้นต่อไก่ 1,000 ตัว ทำสลบด้วย controlled atmospheric stunning ด้วย inert gas หรือ multi-phase หรือไฟฟ้าที่มีประสิทธิภาพโดยไม่แขวนกลับหัวขณะมีสติ และต้อง audit โดย third party พร้อมรายงานความคืบหน้าต่อสาธารณะทุกปี ภายในปี 2026'],['food-industry--fiqc-poultry-export--แรงขับจากตลาด-ผู้บริโภค-และความยั่งยืน','แรงขับจากตลาด ผู้บริโภค และความยั่งยืน','แรงขับจากตลาด ผู้บริโภค และความยั่งยืน \n social pressure ผ่าน social media ไปเร็วมาก ประเด็นที่ผู้บริโภคกดดัน เช่น น้ำมันปาล์ม กากถั่วจากบราซิล ปลาจากแหล่งไม่ยั่งยืน ฮอร์โมนหรือยาปฏิชีวนะ แรงงานทาสและค่าแรงไม่เป็นธรรม ไข่จากการเลี้ยงขังกรง ไข่จากฝูงที่ฆ่าลูกไก่ตัวผู้ เนื้อวัวที่ทำลายป่าแอมะซอน เนื้อหมูจากเล้าจำกัดพื้นที่ บรรจุภัณฑ์ที่รีไซเคิลไม่ได้ \n bbfaw (business benchmark on farm animal welfare) เทียบบริษัทอาหารเป็น tier 1-5 และ tier มีผลต่อมูลค่าหุ้น (โน้ตระบุ cpf อยู่ tier 3) benchmark รุ่นใหม่เพิ่มเกณฑ์ protein diversification (plant-based) \n world bank principle 3: ensure the welfare of animals welfare เป็นองค์ประกอบของ sustainability ทั้งด้านเศรษฐกิจ สังคม สิ่งแวดล้อม และเป็น ethical responsibility \n เป้าหมายของ welfare ฝั่งธุรกิจ: production results ที่ดี, legal responsibility, moral responsibility, company reputation, customers reputation \n trade-off ที่ต้องชั่ง: slow growth, ลดความหนาแน่น, free range ทำให้ใช้ที่ดินมากขึ้น ส่วน cas slaughter ติดประเด็นการค้า (halal) และ animal treatment ที่แย่สัมพันธ์กับ drug resistance \n ผู้ผลิตไทยที่ชูความยั่งยืน: betagro และ cpf 2030 sustainability strategy (มี animal welfare อยู่ในโครง) \n seleggt หยุดการฆ่าลูกไก่ตัวผู้ ด้วยการคัดเพศจากไข่ฟักราววันที่ 9 ทำแล้วในเนเธอร์แลนด์และฝรั่งเศส ใช้ฉลาก free of chick culling ไข่ที่คัดออกนำไปผสมอาหารสัตว์ \n eu แนะนำให้ลูกไก่ได้กินอาหารภายใน 72 ชั่วโมง (เนเธอร์แลนด์ 36 ชั่วโมง) จึงเกิดเทรนด์ฟักไข่ในฟาร์ม (on-farm hatching) เกิดมาก็ได้กินเลย ลด stress จากการขนส่ง \n เทคโนโลยี welfare: monitor เสียงไก่ (ราว 30 แบบ บอกหิว กลัว ป่วย), ชั่งน้ำหนักด้วยกล้อง 3d, ใช้ mri และ ai ตรวจเพศและคุณภาพลูกไก่ในไข่ \n retailer เป็นผู้ขับเคลื่อน: morrisons เร่งการเลี้ยงปล่อยเร็วกว่าเป้า ส่วน waitrose ทำ app ตรวจ welfare และได้รางวัล best retailer จาก compassion in world farming (ciwf) \n กฎหมายขนส่งสัตว์ของ eu ยอมให้ลูกไก่แรกเกิดไม่ต้องได้รับอาหารและน้ำระหว่างเดินทางได้ไม่เกิน 24 ชั่วโมง โดยการเดินทางต้องเสร็จสิ้นภายใน 72 ชั่วโมงหลังฟักออก ซึ่งเป็นที่มาของเกณฑ์ 72 ชั่วโมงในสไลด์ \n การคัดเพศในไข่ฟัก (in ovo sexing) ที่ใช้ตัวอย่าง allantoic fluid ราววันที่ 9 ของการฟักเป็นแนวทางที่พิสูจน์ได้จริง งานทดลอง qpcr ตรวจยีนจำเพาะเพศจาก allantoic fluid ที่วันฟักที่ 6 ถึง 9 ให้ความแม่นยำ 95 ถึง 100 เปอร์เซ็นต์โดยไม่กระทบพัฒนาการของตัวอ่อนอย่างมีนัยสำคัญ'],['food-industry--fiqc-poultry-export--pdo-pgi-และโครงสร้างการรับรอง-cb-ab-iaf','PDO/PGI และโครงสร้างการรับรอง (CB, AB, IAF)','pdo/pgi และโครงสร้างการรับรอง (cb, ab, iaf) \n โน้ตในเอกสารกำกับ pgi ว่าต้องเลี้ยงและแปรรูปใน eu ทั้งหมด และ pdo ว่าอย่างน้อย 1 ขั้นตอน ซึ่งสลับกับนิยามมาตรฐานของ eu (pdo = ทุกขั้นตอนในพื้นที่, pgi = อย่างน้อย 1 ขั้นตอน) ควรตรวจกับสไลด์ปีปัจจุบันก่อนจำ \n โครงสร้างการรับรอง: producer/facility ถูกตรวจโดย cb (certification body) เช่น sgs, nsf, lr \n cb ถูกกำกับโดย ab (accreditation body) ตาม iso 17021 เช่น ukas (united kingdom accreditation service), anab (us), jas-anz (ออสเตรเลีย-นิวซีแลนด์), มกอช. (ไทย) \n ab ถูกตรวจโดย iaf อีกชั้นหนึ่ง \n product certification ใช้ iso/17065 ส่วน management system certification ใช้ iso 17021 \n การแยกมาตรฐานตามสไลด์ถูกต้อง คือ product certification ใช้ iso/iec 17065 (ข้อกำหนดสำหรับหน่วยรับรองผลิตภัณฑ์ กระบวนการ และบริการ) ส่วน management system certification ใช้ iso/iec 17021-1 (ข้อกำหนดสำหรับหน่วยตรวจประเมินและรับรองระบบการจัดการ) และถ้า scheme รับรองผลิตภัณฑ์ต้องตรวจระบบการจัดการด้วย หน่วยรับรองต้องทำตามข้อกำหนดของ 17021-1 ที่เกี่ยวข้องด้วย']]};
